import React, { useState, useMemo } from 'react';
import { User, Chat } from '../../types';

interface SidebarProps {
  currentUser: User;
  onChatSelect: (chat: Chat) => void;
  onProfileClick: () => void;
  activeChatId?: string;
}

const MOCK_CHATS: Chat[] = [
  { id: '1', participants: ['current', 'user_1'], updatedAt: Date.now(), lastMessage: { text: 'Hey, did you see the new update?', senderId: 'user_1', timestamp: Date.now() - 1000 * 60 * 5 } },
  { id: '2', participants: ['current', 'user_2'], updatedAt: Date.now(), lastMessage: { text: 'Let\'s catch up later today.', senderId: 'user_2', timestamp: Date.now() - 1000 * 60 * 60 * 2 } },
  { id: '3', participants: ['current', 'user_3'], updatedAt: Date.now(), lastMessage: { text: 'Check out this attachment!', senderId: 'user_3', timestamp: Date.now() - 1000 * 60 * 60 * 24 } },
];

const MOCK_USERS: Record<string, any> = {
  'user_1': { name: 'Sarah Wilson', photoURL: 'https://picsum.photos/seed/sarah/200', status: 'online' },
  'user_2': { name: 'Alex Rivers', photoURL: 'https://picsum.photos/seed/alex/200', status: 'offline' },
  'user_3': { name: 'Jordan Sparks', photoURL: 'https://picsum.photos/seed/jordan/200', status: 'online' },
};

export const Sidebar: React.FC<SidebarProps> = ({ currentUser, onChatSelect, onProfileClick, activeChatId }) => {
  const [search, setSearch] = useState('');

  const filteredChats = useMemo(() => {
    return MOCK_CHATS.filter(chat => {
      const otherId = chat.participants.find(p => p !== 'current') || '';
      const user = MOCK_USERS[otherId];
      return user.name.toLowerCase().includes(search.toLowerCase());
    });
  }, [search]);

  const formatTime = (ts: number) => {
    const now = Date.now();
    const diff = now - ts;
    if (diff < 24 * 60 * 60 * 1000) {
      return new Date(ts).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
    }
    return new Date(ts).toLocaleDateString([], { month: 'short', day: 'numeric' });
  };

  return (
    <div className="w-80 md:w-96 h-full flex flex-col border-r border-slate-200 dark:border-slate-800 bg-white dark:bg-slate-900 z-10 transition-colors">
      {/* Header */}
      <div className="p-4 flex items-center justify-between">
        <div className="flex items-center gap-3 cursor-pointer group" onClick={onProfileClick}>
          <div className="relative">
            <img 
              src={currentUser.photoURL} 
              alt={currentUser.name} 
              className="w-10 h-10 rounded-full object-cover border-2 border-transparent group-hover:border-indigo-500 transition-all"
            />
            <div className="absolute bottom-0 right-0 w-3 h-3 bg-green-500 rounded-full border-2 border-white dark:border-slate-900"></div>
          </div>
          <div>
            <h3 className="font-bold text-sm leading-none">{currentUser.name}</h3>
            <span className="text-[10px] text-slate-500 uppercase font-bold tracking-wider">My Status: Online</span>
          </div>
        </div>
        <button className="p-2 rounded-full hover:bg-slate-100 dark:hover:bg-slate-800 transition-all text-slate-500">
          <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 5v.01M12 12v.01M12 19v.01M12 6a1 1 0 110-2 1 1 0 010 2zm0 7a1 1 0 110-2 1 1 0 010 2zm0 7a1 1 0 110-2 1 1 0 010 2z" />
          </svg>
        </button>
      </div>

      {/* Search */}
      <div className="px-4 mb-4">
        <div className="relative">
          <span className="absolute inset-y-0 left-3 flex items-center text-slate-400">
            <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" />
            </svg>
          </span>
          <input 
            type="text" 
            placeholder="Search conversations..."
            value={search}
            onChange={(e) => setSearch(e.target.value)}
            className="w-full bg-slate-100 dark:bg-slate-800 border-none rounded-xl py-2 pl-10 pr-4 text-sm focus:ring-2 focus:ring-indigo-500 transition-all outline-none"
          />
        </div>
      </div>

      {/* Chat List */}
      <div className="flex-1 overflow-y-auto space-y-1 p-2">
        {filteredChats.map(chat => {
          const otherId = chat.participants.find(p => p !== 'current') || '';
          const user = MOCK_USERS[otherId];
          const isActive = activeChatId === chat.id;

          return (
            <div 
              key={chat.id}
              onClick={() => onChatSelect(chat)}
              className={`flex items-center gap-3 p-3 rounded-xl cursor-pointer transition-all ${isActive ? 'bg-indigo-500 text-white' : 'hover:bg-slate-100 dark:hover:bg-slate-800'}`}
            >
              <div className="relative flex-shrink-0">
                <img src={user.photoURL} alt={user.name} className="w-12 h-12 rounded-full object-cover" />
                {user.status === 'online' && (
                  <div className="absolute bottom-0 right-0 w-3 h-3 bg-green-500 rounded-full border-2 border-white dark:border-slate-900"></div>
                )}
              </div>
              <div className="flex-1 min-w-0">
                <div className="flex justify-between items-baseline">
                  <h4 className={`font-semibold text-sm truncate ${isActive ? 'text-white' : 'text-slate-900 dark:text-slate-100'}`}>{user.name}</h4>
                  <span className={`text-[10px] font-medium ${isActive ? 'text-indigo-100' : 'text-slate-500'}`}>
                    {chat.lastMessage ? formatTime(chat.lastMessage.timestamp) : ''}
                  </span>
                </div>
                <p className={`text-xs truncate mt-0.5 ${isActive ? 'text-indigo-100' : 'text-slate-500 dark:text-slate-400'}`}>
                  {chat.lastMessage?.text || 'No messages yet'}
                </p>
              </div>
            </div>
          );
        })}
      </div>

      {/* Bottom Action */}
      <div className="p-4 border-t border-slate-200 dark:border-slate-800">
        <button className="w-full py-2 bg-indigo-500 hover:bg-indigo-600 text-white rounded-xl text-sm font-bold shadow-lg shadow-indigo-500/20 active:scale-95 transition-all flex items-center justify-center gap-2">
          <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 4v16m8-8H4" />
          </svg>
          New Chat
        </button>
      </div>
    </div>
  );
};

import React, { useState, useEffect, useRef } from 'react';
import { User, Chat, Message } from '../../types';
import { MessageBubble } from './MessageBubble';

interface ChatWindowProps {
  chat: Chat;
  currentUser: User;
  onClose: () => void;
}

const MOCK_MESSAGES: Message[] = [
  { id: 'm1', senderId: 'user_1', text: 'Hey there! How are you doing?', type: 'text', timestamp: Date.now() - 1000 * 60 * 10, status: 'seen' },
  { id: 'm2', senderId: 'current', text: 'I am doing great! Working on that new project.', type: 'text', timestamp: Date.now() - 1000 * 60 * 8, status: 'seen' },
  { id: 'm3', senderId: 'user_1', text: 'Nice! Is it the React one?', type: 'text', timestamp: Date.now() - 1000 * 60 * 5, status: 'seen' },
  { id: 'm4', senderId: 'current', text: 'Yes, with Tailwind and Firebase.', type: 'text', timestamp: Date.now() - 1000 * 60 * 2, status: 'delivered' },
];

export const ChatWindow: React.FC<ChatWindowProps> = ({ chat, currentUser, onClose }) => {
  const [messages, setMessages] = useState<Message[]>(MOCK_MESSAGES);
  const [inputText, setInputText] = useState('');
  const [isTyping, setIsTyping] = useState(false);
  const scrollRef = useRef<HTMLDivElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const otherId = chat.participants.find(p => p !== 'current') || '';
  const otherUser = {
    name: otherId === 'user_1' ? 'Sarah Wilson' : otherId === 'user_2' ? 'Alex Rivers' : 'Jordan Sparks',
    photoURL: `https://picsum.photos/seed/${otherId}/200`,
    status: 'online' as const
  };

  useEffect(() => {
    scrollToBottom();
  }, [messages]);

  const scrollToBottom = () => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  };

  const handleSend = (e?: React.FormEvent) => {
    e?.preventDefault();
    if (!inputText.trim()) return;

    const newMessage: Message = {
      id: 'm_' + Math.random().toString(36).substr(2, 9),
      senderId: 'current',
      text: inputText,
      type: 'text',
      timestamp: Date.now(),
      status: 'sent'
    };

    setMessages([...messages, newMessage]);
    setInputText('');

    // Mock auto-reply
    setTimeout(() => {
      setIsTyping(true);
      setTimeout(() => {
        setIsTyping(false);
        const reply: Message = {
          id: 'r_' + Math.random().toString(36).substr(2, 9),
          senderId: otherId,
          text: 'This looks amazing!',
          type: 'text',
          timestamp: Date.now(),
          status: 'seen'
        };
        setMessages(prev => [...prev, reply]);
      }, 1500);
    }, 1000);
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    // Simulate file upload
    const newMessage: Message = {
      id: 'f_' + Math.random().toString(36).substr(2, 9),
      senderId: 'current',
      text: `Sent a file: ${file.name}`,
      type: file.type.startsWith('image/') ? 'image' : 'file',
      timestamp: Date.now(),
      status: 'sent',
      fileName: file.name,
      fileUrl: URL.createObjectURL(file)
    };
    setMessages([...messages, newMessage]);
  };

  return (
    <div className="flex-1 flex flex-col h-full bg-slate-50 dark:bg-slate-900/40 relative">
      {/* Top Header */}
      <div className="p-4 flex items-center justify-between glass z-10 border-b border-slate-200 dark:border-slate-800">
        <div className="flex items-center gap-3">
          <button onClick={onClose} className="lg:hidden p-2 rounded-full hover:bg-slate-200 dark:hover:bg-slate-800">
            <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M15 19l-7-7 7-7" />
            </svg>
          </button>
          <div className="relative">
            <img src={otherUser.photoURL} alt={otherUser.name} className="w-10 h-10 rounded-full object-cover" />
            <div className="absolute bottom-0 right-0 w-3 h-3 bg-green-500 rounded-full border-2 border-white dark:border-slate-900"></div>
          </div>
          <div>
            <h3 className="font-bold text-sm leading-none">{otherUser.name}</h3>
            <span className="text-[10px] text-green-500 font-bold uppercase tracking-wider">Online</span>
          </div>
