import { useState, useEffect } from 'react';
import { User } from '../types';

const DB_KEY = 'gemini_chat_registered_users';
const SESSION_KEY = 'chat_user';

export const useAuth = () => {
  const [user, setUser] = useState<User | null>(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const savedUser = localStorage.getItem(SESSION_KEY);
    if (savedUser) {
      setUser(JSON.parse(savedUser));
    }
    setLoading(false);
  }, []);

  const getDb = (): any[] => {
    const db = localStorage.getItem(DB_KEY);
    return db ? JSON.parse(db) : [];
  };

  const saveToDb = (users: any[]) => {
    localStorage.setItem(DB_KEY, JSON.stringify(users));
  };

  const signup = async (email: string, pass: string, name: string) => {
    const db = getDb();
    if (db.find(u => u.email === email)) {
      throw new Error("User already exists with this email.");
    }

    const newUser: User = {
      uid: 'user_' + Math.random().toString(36).substr(2, 9),
      name,
      email,
      photoURL: `https://picsum.photos/seed/${email}/200`,
      status: 'online',
      lastSeen: Date.now()
    };

    // Store in our mock database (with password)
    db.push({ ...newUser, password: pass });
    saveToDb(db);

    // Login automatically
    login(newUser);
    return newUser;
  };

  const loginWithEmail = async (email: string, pass: string) => {
    const db = getDb();
    const found = db.find(u => u.email === email);

    if (!found) {
      throw new Error("No account found with this email.");
    }
    if (found.password !== pass) {
      throw new Error("Incorrect password.");
    }

    // Strip password before setting state
    const { password, ...userProfile } = found;
    login(userProfile as User);
    return userProfile as User;
  };

  const login = (u: User) => {
    setUser(u);
    localStorage.setItem(SESSION_KEY, JSON.stringify(u));
  };

  const logout = () => {
    setUser(null);
    localStorage.removeItem(SESSION_KEY);
  };

  return { user, loading, signup, login: loginWithEmail, logout };
};

