/**
 * MOCK FIREBASE IMPLEMENTATION
 * This file mimics the Firebase SDK v10+ interface to provide a "fully functional"
 * experience without requiring a real API Key. In a real production environment,
 * you would swap these mocks for the real @firebase/app and @firebase/auth packages.
 */

const STORAGE_KEY_USERS = 'gemini_chat_db_users';
const STORAGE_KEY_MESSAGES = 'gemini_chat_db_messages';

// Helper to interact with LocalStorage
const getLocal = (key: string) => JSON.parse(localStorage.getItem(key) || '[]');
const saveLocal = (key: string, data: any) => localStorage.setItem(key, JSON.stringify(data));

export const auth: any = {
  currentUser: null,
  onAuthStateChanged: (callback: Function) => {
    const saved = localStorage.getItem('chat_session');
    if (saved) {
      const user = JSON.parse(saved);
      auth.currentUser = user;
      callback(user);
    } else {
      callback(null);
    }
    return () => {}; // Unsubscribe mock
  }
};

export const db: any = {
  collection: (name: string) => ({ name }),
};

export const googleProvider = {};

// Mock Auth Functions
export const signInWithEmailAndPassword = async (authObj: any, email: string, pass: string) => {
  const users = getLocal(STORAGE_KEY_USERS);
  const user = users.find((u: any) => u.email === email && u.password === pass);
  if (!user) throw new Error("auth/user-not-found");
  const { password, ...userProfile } = user;
  auth.currentUser = userProfile;
  localStorage.setItem('chat_session', JSON.stringify(userProfile));
  return { user: userProfile };
};

export const createUserWithEmailAndPassword = async (authObj: any, email: string, pass: string) => {
  const users = getLocal(STORAGE_KEY_USERS);
  if (users.find((u: any) => u.email === email)) throw new Error("auth/email-already-in-use");
  const newUser = { uid: crypto.randomUUID(), email, password: pass, status: 'online', lastSeen: Date.now() };
  users.push(newUser);
  saveLocal(STORAGE_KEY_USERS, users);
  return { user: newUser };
};

export const signInWithPopup = async () => {
  const mockGoogleUser = {
    uid: 'google_' + Math.random().toString(36).substr(2, 9),
    displayName: 'Google User',
    email: 'google@example.com',
    photoURL: 'https://lh3.googleusercontent.com/a/default-user',
  };
  auth.currentUser = mockGoogleUser;
  localStorage.setItem('chat_session', JSON.stringify(mockGoogleUser));
  return { user: mockGoogleUser };
};

export const signOut = async () => {
  auth.currentUser = null;
  localStorage.removeItem('chat_session');
};

export const updateProfile = async (user: any, updates: any) => {
  const users = getLocal(STORAGE_KEY_USERS);
  const idx = users.findIndex((u: any) => u.uid === user.uid);
  if (idx !== -1) {
    users[idx] = { ...users[idx], ...updates };
    saveLocal(STORAGE_KEY_USERS, users);
    localStorage.setItem('chat_session', JSON.stringify(users[idx]));
  }
};

// Mock Firestore Functions
export const doc = (db: any, coll: string, id: string) => ({ coll, id });
export const getDoc = async (docRef: any) => {
  const data = getLocal(`db_${docRef.coll}`).find((item: any) => item.uid === docRef.id || item.id === docRef.id);
  return { exists: () => !!data, data: () => data };
};
export const setDoc = async (docRef: any, data: any, options?: any) => {
  const collection = getLocal(`db_${docRef.coll}`);
  const idx = collection.findIndex((item: any) => item.uid === docRef.id || item.id === docRef.id);
  if (idx !== -1) {
    collection[idx] = options?.merge ? { ...collection[idx], ...data } : data;
  } else {
    collection.push({ ...data, id: docRef.id });
  }
  saveLocal(`db_${docRef.coll}`, collection);
};

export const serverTimestamp = () => Date.now();

import { useState, useEffect } from 'react';
import { 
  auth, 
  db, 
  signInWithEmailAndPassword, 
  createUserWithEmailAndPassword, 
  signInWithPopup, 
  signOut, 
  updateProfile,
  doc,
  setDoc,
  getDoc,
  serverTimestamp
} from '../firebase';
import { User } from '../types';

export const useAuth = () => {
  const [user, setUser] = useState<User | null>(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    // Listen to mock auth state changes
    const unsubscribe = auth.onAuthStateChanged(async (mockUser: any) => {
      if (mockUser) {
        const userDoc = await getDoc(doc(db, 'users', mockUser.uid));
        const userData = userDoc.data();

        setUser({
          uid: mockUser.uid,
          name: mockUser.displayName || userData?.name || 'Anonymous',
          email: mockUser.email || userData?.email || '',
          photoURL: mockUser.photoURL || userData?.photoURL || `https://picsum.photos/seed/${mockUser.uid}/200`,
          status: 'online',
          lastSeen: Date.now(),
          ...userData
        });
      } else {
        setUser(null);
      }
      setLoading(false);
    });

    return () => unsubscribe();
  }, []);

  const syncUserToFirestore = async (u: any) => {
    const userRef = doc(db, 'users', u.uid);
    await setDoc(userRef, {
      uid: u.uid,
      name: u.displayName || u.name,
      email: u.email,
      photoURL: u.photoURL,
      lastSeen: serverTimestamp(),
      status: 'online'
    }, { merge: true });
  };

  const signup = async (email: string, pass: string, name: string) => {
    const res = await createUserWithEmailAndPassword(auth, email, pass);
    await updateProfile(res.user, { 
      displayName: name,
      photoURL: `https://picsum.photos/seed/${res.user.uid}/200`
    });
    const updatedUser = { ...res.user, displayName: name };
    await syncUserToFirestore(updatedUser);
    return updatedUser;
  };

  const login = async (email: string, pass: string) => {
    const res = await signInWithEmailAndPassword(auth, email, pass);
    await syncUserToFirestore(res.user);
    return res.user;
  };

  const googleSignIn = async () => {
    const res = await signInWithPopup();
    await syncUserToFirestore(res.user);
    return res.user;
  };

  const logout = async () => {
    if (user) {
      await setDoc(doc(db, 'users', user.uid), { 
        status: 'offline', 
        lastSeen: serverTimestamp() 
      }, { merge: true });
    }
    await signOut();
  };

  return { user, loading, signup, login, googleSignIn, logout };
};

import { GoogleGenAI } from "@google/genai";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || "AI_KEY_PLACEHOLDER" });

export const getAIResponse = async (prompt: string) => {
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
      config: {
        systemInstruction: "You are a helpful and witty chat assistant. Keep responses brief and conversational, suitable for a mobile chat app. If asked about facts, use common knowledge or admit if unsure.",
      }
    });
    return response.text;
  } catch (error) {
    console.error("Gemini Error:", error);
    return "Sorry, I'm having a bit of trouble connecting to my brain right now. 🤖";
  }
};

import React, { useState, useEffect, useRef } from 'react';
