}

// Initial Mock Messages for context
const MOCK_MESSAGES: Message[] = [
  { id: 'm1', senderId: 'user_1', text: 'Hey there! How are you doing?', type: 'text', timestamp: Date.now() - 1000 * 60 * 10, status: 'seen' },
  { id: 'm2', senderId: 'current', text: 'I am doing great! Working on that new project.', type: 'text', timestamp: Date.now() - 1000 * 60 * 8, status: 'seen' },
];

export const ChatWindow: React.FC<ChatWindowProps> = ({ chat, currentUser, onClose }) => {
  const [messages, setMessages] = useState<Message[]>(MOCK_MESSAGES);
  const [inputText, setInputText] = useState('');
  const [isTyping, setIsTyping] = useState(false);
  const scrollRef = useRef<HTMLDivElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const otherId = chat.participants.find(p => p !== 'current') || '';
  const otherUser = {
    name: otherId === 'user_1' ? 'Sarah Wilson' : otherId === 'user_2' ? 'Alex Rivers' : 'Jordan Sparks',
    photoURL: `https://picsum.photos/seed/${otherId}/200`,
    status: 'online' as const
  };

  useEffect(() => {
    scrollToBottom();
  }, [messages, isTyping]);

  const scrollToBottom = () => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  };

  const handleSend = async (e?: React.FormEvent) => {
    e?.preventDefault();
    const text = inputText.trim();
    if (!text) return;

    const newMessage: Message = {
      id: 'm_' + Math.random().toString(36).substr(2, 9),
      senderId: 'current',
      text: text,
      type: 'text',
      timestamp: Date.now(),
      status: 'sent'
    };

    setMessages(prev => [...prev, newMessage]);
    setInputText('');

    // AI Trigger: Check if message starts with /ai or is a question
    if (text.toLowerCase().startsWith('/ai')) {
      setIsTyping(true);
      const prompt = text.replace('/ai', '').trim();
      const aiReply = await getAIResponse(prompt || "Tell me a joke");
      setIsTyping(false);

      const aiMessage: Message = {
        id: 'ai_' + Date.now(),
        senderId: 'gemini_ai',
        text: aiReply || "I'm thinking...",
        type: 'text',
        timestamp: Date.now(),
        status: 'seen'
      };
      setMessages(prev => [...prev, aiMessage]);
    } else {
      // Regular Mock auto-reply
      setTimeout(() => {
        setIsTyping(true);
        setTimeout(() => {
          setIsTyping(false);
          const reply: Message = {
            id: 'r_' + Date.now(),
            senderId: otherId,
            text: 'Got it! 👍',
            type: 'text',
            timestamp: Date.now(),
            status: 'seen'
          };
          setMessages(prev => [...prev, reply]);
        }, 1200);
      }, 800);
    }
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    const newMessage: Message = {
      id: 'f_' + Date.now(),
      senderId: 'current',
      text: `Sent a file: ${file.name}`,
      type: file.type.startsWith('image/') ? 'image' : 'file',
      timestamp: Date.now(),
      status: 'sent',
      fileName: file.name,
      fileUrl: URL.createObjectURL(file)
    };
    setMessages(prev => [...prev, newMessage]);
  };

  return (
    <div className="flex-1 flex flex-col h-full bg-slate-50 dark:bg-slate-900/40 relative">
      {/* Top Header */}
      <div className="p-4 flex items-center justify-between glass z-10 border-b border-slate-200 dark:border-slate-800">
        <div className="flex items-center gap-3">
          <button onClick={onClose} className="lg:hidden p-2 rounded-full hover:bg-slate-200 dark:hover:bg-slate-800">
            <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M15 19l-7-7 7-7" />
            </svg>
          </button>
          <div className="relative">
            <img src={otherUser.photoURL} alt={otherUser.name} className="w-10 h-10 rounded-full object-cover" />
            <div className="absolute bottom-0 right-0 w-3 h-3 bg-green-500 rounded-full border-2 border-white dark:border-slate-900"></div>
          </div>
          <div>
            <h3 className="font-bold text-sm leading-none">{otherUser.name}</h3>
            <span className="text-[10px] text-green-500 font-bold uppercase tracking-wider">Online</span>
          </div>
        </div>
        <div className="flex items-center gap-2">
          <button className="hidden md:flex items-center gap-2 px-3 py-1.5 bg-indigo-500/10 text-indigo-500 rounded-full text-[10px] font-bold uppercase tracking-wider hover:bg-indigo-500/20 transition-all border border-indigo-500/20">
            <span className="w-1.5 h-1.5 bg-indigo-500 rounded-full animate-pulse"></span>
            AI Enabled
          </button>
        </div>
      </div>

      {/* Messages Scroller */}
      <div ref={scrollRef} className="flex-1 overflow-y-auto p-4 space-y-4 scroll-smooth">
        {messages.map(msg => (
          <div key={msg.id} className="animate-in fade-in slide-in-from-bottom-2 duration-300">
             <MessageBubble 
              message={msg} 
              isOwn={msg.senderId === 'current'} 
              isAI={msg.senderId === 'gemini_ai'}
            />
          </div>
        ))}
        {isTyping && (
          <div className="flex items-end gap-2 max-w-[80%]">
            <div className="bg-white dark:bg-slate-800 rounded-2xl rounded-bl-none p-3 shadow-sm border border-slate-100 dark:border-slate-700">
              <div className="flex gap-1">
                <div className="w-1.5 h-1.5 bg-indigo-400 rounded-full animate-bounce"></div>
                <div className="w-1.5 h-1.5 bg-indigo-400 rounded-full animate-bounce [animation-delay:-0.15s]"></div>
                <div className="w-1.5 h-1.5 bg-indigo-400 rounded-full animate-bounce [animation-delay:-0.3s]"></div>
              </div>
            </div>
          </div>
        )}
      </div>

      {/* Input Area */}
      <div className="p-4 glass border-t border-slate-200 dark:border-slate-800">
        <form onSubmit={handleSend} className="flex items-end gap-3 max-w-5xl mx-auto">
