  const { password, ...userProfile } = newUser;
  auth.currentUser = userProfile;
  localStorage.setItem(STORAGE_KEY_SESSION, JSON.stringify(userProfile));
  notifyListeners(userProfile);

  return { user: userProfile };
};

export const signInWithPopup = async () => {
  const mockGoogleUser = {
    uid: 'google_' + Math.random().toString(36).substr(2, 9),
    displayName: 'Google User',
    email: 'google@example.com',
    photoURL: 'https://lh3.googleusercontent.com/a/default-user',
  };
  auth.currentUser = mockGoogleUser;
  localStorage.setItem(STORAGE_KEY_SESSION, JSON.stringify(mockGoogleUser));
  notifyListeners(mockGoogleUser);
  return { user: mockGoogleUser };
};

export const signOut = async () => {
  auth.currentUser = null;
  localStorage.removeItem(STORAGE_KEY_SESSION);
  notifyListeners(null);
};

export const updateProfile = async (user: any, updates: any) => {
  const users = getLocal(STORAGE_KEY_USERS);
  const idx = users.findIndex((u: any) => u.uid === user.uid);
  if (idx !== -1) {
    users[idx] = { ...users[idx], ...updates };
    saveLocal(STORAGE_KEY_USERS, users);

    const updatedProfile = { ...users[idx] };
    delete updatedProfile.password;

    auth.currentUser = updatedProfile;
    localStorage.setItem(STORAGE_KEY_SESSION, JSON.stringify(updatedProfile));
    notifyListeners(updatedProfile);
  }
};

// Mock Firestore Functions
export const doc = (db: any, coll: string, id: string) => ({ coll, id });
export const getDoc = async (docRef: any) => {
  const data = getLocal(`db_${docRef.coll}`).find((item: any) => item.uid === docRef.id || item.id === docRef.id);
  return { exists: () => !!data, data: () => data };
};
export const setDoc = async (docRef: any, data: any, options?: any) => {
  const collection = getLocal(`db_${docRef.coll}`);
  const idx = collection.findIndex((item: any) => item.uid === docRef.id || item.id === docRef.id);
  if (idx !== -1) {
    collection[idx] = options?.merge ? { ...collection[idx], ...data } : data;
  } else {
    collection.push({ ...data, id: docRef.id });
  }
  saveLocal(`db_${docRef.coll}`, collection);
};

export const serverTimestamp = () => Date.now();

import { useState, useEffect } from 'react';
import { 
  auth, 
  db, 
  signInWithEmailAndPassword, 
  createUserWithEmailAndPassword, 
  signInWithPopup, 
  signOut, 
  updateProfile,
  doc,
  setDoc,
  getDoc,
  serverTimestamp
} from '../firebase';
import { User } from '../types';

export const useAuth = () => {
  const [user, setUser] = useState<User | null>(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    // Listen to mock auth state changes
    const unsubscribe = auth.onAuthStateChanged(async (mockUser: any) => {
      if (mockUser) {
        try {
          const userDoc = await getDoc(doc(db, 'users', mockUser.uid));
          const userData = userDoc.data();

          setUser({
            uid: mockUser.uid,
            name: mockUser.displayName || userData?.name || mockUser.name || 'Anonymous',
            email: mockUser.email || userData?.email || '',
            photoURL: mockUser.photoURL || userData?.photoURL || `https://picsum.photos/seed/${mockUser.uid}/200`,
            status: 'online',
            lastSeen: Date.now(),
            ...userData
          });
        } catch (e) {
          // Fallback if firestore doc doesn't exist yet (signup phase)
          setUser({
            uid: mockUser.uid,
            name: mockUser.name || 'User',
            email: mockUser.email || '',
            photoURL: mockUser.photoURL || `https://picsum.photos/seed/${mockUser.uid}/200`,
            status: 'online',
            lastSeen: Date.now()
          });
        }
      } else {
        setUser(null);
      }
      setLoading(false);
    });

    return () => unsubscribe();
  }, []);

  const syncUserToFirestore = async (u: any) => {
    const userRef = doc(db, 'users', u.uid);
    await setDoc(userRef, {
      uid: u.uid,
      name: u.displayName || u.name,
      email: u.email,
      photoURL: u.photoURL,
      lastSeen: serverTimestamp(),
      status: 'online'
    }, { merge: true });
  };

  const signup = async (email: string, pass: string, name: string) => {
    const res = await createUserWithEmailAndPassword(auth, email, pass);
    // Immediately update profile to include name
    await updateProfile(res.user, { 
      displayName: name,
      name: name,
      photoURL: `https://picsum.photos/seed/${res.user.uid}/200`
    });

    const updatedUser = { ...res.user, name, displayName: name };
    await syncUserToFirestore(updatedUser);
    return updatedUser;
  };

  const login = async (email: string, pass: string) => {
    const res = await signInWithEmailAndPassword(auth, email, pass);
    await syncUserToFirestore(res.user);
    return res.user;
  };

  const googleSignIn = async () => {
    const res = await signInWithPopup();
    await syncUserToFirestore(res.user);
    return res.user;
  };

  const logout = async () => {
    if (user) {
      await setDoc(doc(db, 'users', user.uid), { 
        status: 'offline', 
        lastSeen: serverTimestamp() 
      }, { merge: true });
    }
    await signOut();
  };

  return { user, loading, signup, login, googleSignIn, logout };
};

