              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M15 19l-7-7 7-7" />
            </svg>
          </button>
          <div className="relative">
            <img src={otherUser.photoURL} alt={otherUser.name} className="w-9 h-9 md:w-10 md:h-10 rounded-full object-cover" />
            <div className="absolute bottom-0 right-0 w-2.5 h-2.5 bg-green-500 rounded-full border-2 border-white dark:border-slate-900"></div>
          </div>
          <div className="min-w-0">
            <h3 className="font-bold text-sm leading-none truncate">{otherUser.name}</h3>
            <span className="text-[10px] text-green-500 font-bold uppercase tracking-wider">Online</span>
          </div>
        </div>
        <div className="flex items-center gap-2">
          <button className="flex items-center gap-2 px-3 py-1.5 bg-indigo-500/10 text-indigo-500 rounded-full text-[10px] font-bold uppercase tracking-wider hover:bg-indigo-500/20 transition-all border border-indigo-500/20">
            <span className="w-1.5 h-1.5 bg-indigo-500 rounded-full animate-pulse"></span>
            <span className="hidden xs:inline">AI Assistant</span>
            <span className="xs:hidden">AI</span>
          </button>
        </div>
      </div>

