              </svg>
            </button>
            <input type="file" ref={fileInputRef} className="hidden" onChange={handleFileUpload} />
          </div>

          <div className="flex-1 relative">
            <textarea 
              value={inputText}
              onChange={(e) => setInputText(e.target.value)}
              onKeyDown={(e) => {
                if (e.key === 'Enter' && !e.shiftKey) {
                  e.preventDefault();
                  handleSend();
                }
              }}
              placeholder="Type /ai to ask Gemini..."
              rows={1}
              className="w-full bg-slate-100 dark:bg-slate-800 border-none rounded-2xl py-2.5 md:py-3 pl-4 pr-12 text-sm focus:ring-2 focus:ring-indigo-500 outline-none resize-none min-h-[44px] max-h-32 transition-all"
            />
          </div>

          <button 
            type="submit"
            disabled={!inputText.trim()}
            className={`p-2.5 md:p-3 rounded-2xl shadow-lg transition-all active:scale-95 flex items-center justify-center ${
              inputText.trim() 
              ? 'bg-indigo-500 hover:bg-indigo-600 text-white shadow-indigo-500/20' 
              : 'bg-slate-200 dark:bg-slate-700 text-slate-400 cursor-not-allowed'
            }`}
          >
            <svg className="w-6 h-6 transform rotate-90" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 19l9 2-9-18-9 18 9-2zm0 0v-8" />
            </svg>
          </button>
        </form>
      </div>
    </div>
  );
};

export interface User {
  uid: string;
  name: string;
  email: string;
  photoURL: string;
  status: 'online' | 'offline';
  lastSeen: number;
  bio?: string;
}

export type MessageType = 'text' | 'image' | 'file' | 'voice';
export type MessageStatus = 'sent' | 'delivered' | 'seen';

export interface Message {
  id: string;
  senderId: string;
  text: string;
  type: MessageType;
  timestamp: number;
  status: MessageStatus;
