const STORAGE_KEY_USERS = 'gemini_chat_db_users';
const STORAGE_KEY_SESSION = 'chat_session';
const STORAGE_KEY_STORIES = 'gemini_chat_db_stories';

// Helper to interact with LocalStorage
const getLocal = (key: string) => JSON.parse(localStorage.getItem(key) || '[]');
const saveLocal = (key: string, data: any) => localStorage.setItem(key, JSON.stringify(data));

// Internal state for listeners
let authListeners: Function[] = [];

const notifyListeners = (user: any) => {
  authListeners.forEach(cb => cb(user));
};

export const auth: any = {
  currentUser: null,
  onAuthStateChanged: (callback: Function) => {
    authListeners.push(callback);
    const saved = localStorage.getItem(STORAGE_KEY_SESSION);
    if (saved) {
      const user = JSON.parse(saved);
      auth.currentUser = user;
      callback(user);
    } else {
      callback(null);
    }
    return () => {
      authListeners = authListeners.filter(l => l !== callback);
    };
  }
};

export const db: any = {
  collection: (name: string) => ({ name }),
};

export const googleProvider = {};

// Mock Auth Functions
export const signInWithEmailAndPassword = async (authObj: any, email: string, pass: string) => {
  const users = getLocal(STORAGE_KEY_USERS);
  const user = users.find((u: any) => u.email === email);
  if (!user) throw new Error("auth/user-not-found");
  if (user.password !== pass) throw new Error("auth/wrong-password");
  const { password, ...userProfile } = user;
  auth.currentUser = userProfile;
  localStorage.setItem(STORAGE_KEY_SESSION, JSON.stringify(userProfile));
  notifyListeners(userProfile);
  return { user: userProfile };
};

export const createUserWithEmailAndPassword = async (authObj: any, email: string, pass: string) => {
  const users = getLocal(STORAGE_KEY_USERS);
  if (users.find((u: any) => u.email === email)) throw new Error("auth/email-already-in-use");
  const newUser = { 
    uid: crypto.randomUUID(), 
    email, 
    password: pass, 
    status: 'online', 
    lastSeen: Date.now(),
    photoURL: `https://picsum.photos/seed/${Math.random()}/200`,
    name: email.split('@')[0]
  };
  users.push(newUser);
  saveLocal(STORAGE_KEY_USERS, users);
  const { password, ...userProfile } = newUser;
  auth.currentUser = userProfile;
  localStorage.setItem(STORAGE_KEY_SESSION, JSON.stringify(userProfile));
  notifyListeners(userProfile);
  return { user: userProfile };
};

export const signInWithPopup = async () => {
  const mockGoogleUser = {
    uid: 'google_' + Math.random().toString(36).substr(2, 9),
    displayName: 'Google User',
    email: 'google@example.com',
    photoURL: 'https://lh3.googleusercontent.com/a/default-user',
  };
  auth.currentUser = mockGoogleUser;
  localStorage.setItem(STORAGE_KEY_SESSION, JSON.stringify(mockGoogleUser));
  notifyListeners(mockGoogleUser);
  return { user: mockGoogleUser };
};

export const signOut = async () => {
  auth.currentUser = null;
  localStorage.removeItem(STORAGE_KEY_SESSION);
  notifyListeners(null);
};

export const updateProfile = async (user: any, updates: any) => {
  const users = getLocal(STORAGE_KEY_USERS);
  const idx = users.findIndex((u: any) => u.uid === user.uid);
  if (idx !== -1) {
    users[idx] = { ...users[idx], ...updates };
    saveLocal(STORAGE_KEY_USERS, users);
    const updatedProfile = { ...users[idx] };
    delete updatedProfile.password;
    auth.currentUser = updatedProfile;
    localStorage.setItem(STORAGE_KEY_SESSION, JSON.stringify(updatedProfile));
    notifyListeners(updatedProfile);
  }
};

// Mock Story Functions
export const addStory = async (story: any) => {
  const stories = getLocal(STORAGE_KEY_STORIES);
  stories.push(story);
  saveLocal(STORAGE_KEY_STORIES, stories);
};

export const getStories = async () => {
  const stories = getLocal(STORAGE_KEY_STORIES);
  // Filter stories older than 24h
  const now = Date.now();
  const validStories = stories.filter((s: any) => (now - s.timestamp) < (24 * 60 * 60 * 1000));
  if (validStories.length !== stories.length) saveLocal(STORAGE_KEY_STORIES, validStories);
  return validStories;
};

// Mock Firestore Functions
export const doc = (db: any, coll: string, id: string) => ({ coll, id });
export const getDoc = async (docRef: any) => {
  const data = getLocal(`db_${docRef.coll}`).find((item: any) => item.uid === docRef.id || item.id === docRef.id);
  return { exists: () => !!data, data: () => data };
};
export const setDoc = async (docRef: any, data: any, options?: any) => {
  const collection = getLocal(`db_${docRef.coll}`);
  const idx = collection.findIndex((item: any) => item.uid === docRef.id || item.id === docRef.id);
  if (idx !== -1) {
    collection[idx] = options?.merge ? { ...collection[idx], ...data } : data;
  } else {
    collection.push({ ...data, id: docRef.id });
  }
  saveLocal(`db_${docRef.coll}`, collection);
};

