                />
              </div>
            </div>
            <span className="text-[11px] font-semibold text-slate-500 dark:text-slate-400 truncate w-16 text-center">
              {firstStory.userName.split(' ')[0]}
            </span>
          </div>
        );
      })}
    </div>
  );
};

import React, { useState, useRef } from 'react';
import { User, Story } from '../../types';
import { addStory } from '../../firebase';

interface StoryUploadProps {
  currentUser: User;
  onClose: () => void;
}

export const StoryUpload: React.FC<StoryUploadProps> = ({ currentUser, onClose }) => {
  const [file, setFile] = useState<File | null>(null);
  const [preview, setPreview] = useState<string | null>(null);
  const [caption, setCaption] = useState('');
  const [isUploading, setIsUploading] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const selected = e.target.files?.[0];
    if (selected) {
      setFile(selected);
      const reader = new FileReader();
      reader.onload = (event) => setPreview(event.target?.result as string);
      reader.readAsDataURL(selected);
    }
  };

  const handleUpload = async () => {
    if (!preview || !file) return;
    setIsUploading(true);

    const newStory: Story = {
      id: crypto.randomUUID(),
      userId: currentUser.uid,
      userName: currentUser.name,
      userPhoto: currentUser.photoURL,
      mediaUrl: preview,
      mediaType: file.type.startsWith('video/') ? 'video' : 'image',
      caption: caption,
      timestamp: Date.now()
    };

    await addStory(newStory);
    setIsUploading(false);
    onClose();
  };

  return (
    <div className="fixed inset-0 z-[100] bg-slate-950 flex flex-col items-center justify-center p-4">
      <button onClick={onClose} className="absolute top-6 left-6 p-3 text-white hover:bg-white/10 rounded-full transition-all">
        <svg className="w-8 h-8" fill="none" stroke="currentColor" viewBox="0 0 24 24">
          <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M6 18L18 6M6 6l12 12" />
        </svg>
      </button>

      {!preview ? (
        <div className="text-center space-y-6">
          <div className="w-24 h-24 bg-white/10 rounded-full flex items-center justify-center mx-auto mb-6">
            <svg className="w-12 h-12 text-white/40" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M4 16l4.586-4.586a2 2 0 012.828 0L16 16m-2-2l1.586-1.586a2 2 0 012.828 0L20 14m-6-6h.01M6 20h12a2 2 0 002-2V6a2 2 0 00-2-2H6a2 2 0 00-2 2v12a2 2 0 002 2z" />
            </svg>
          </div>
          <h2 className="text-2xl font-bold text-white">Add to Story</h2>
          <p className="text-white/40 max-w-xs mx-auto">Share a photo or video with your contacts. Stories disappear after 24 hours.</p>
          <button 
            onClick={() => fileInputRef.current?.click()}
            className="px-8 py-4 bg-indigo-500 hover:bg-indigo-600 text-white rounded-2xl font-bold shadow-xl shadow-indigo-500/20 active:scale-95 transition-all"
          >
            Choose from Gallery
          </button>
          <input type="file" ref={fileInputRef} onChange={handleFileChange} accept="image/*,video/*" className="hidden" />
        </div>
      ) : (
        <div className="w-full max-w-md flex flex-col gap-6">
          <div className="relative aspect-[9/16] bg-black rounded-3xl overflow-hidden shadow-2xl ring-1 ring-white/10">
            {file?.type.startsWith('video/') ? (
              <video src={preview} className="w-full h-full object-contain" autoPlay muted loop />
            ) : (
              <img src={preview} alt="Preview" className="w-full h-full object-contain" />
            )}

            <div className="absolute bottom-0 inset-x-0 p-6 bg-gradient-to-t from-black/80 to-transparent">
               <textarea 
                value={caption}
                onChange={(e) => setCaption(e.target.value)}
                placeholder="Add a caption..."
                className="w-full bg-white/10 backdrop-blur-md border border-white/20 rounded-2xl p-4 text-white placeholder-white/40 focus:ring-2 focus:ring-indigo-500 outline-none resize-none"
                rows={2}
              />
            </div>
          </div>

          <div className="flex gap-4">
            <button 
              onClick={() => { setFile(null); setPreview(null); }}
              className="flex-1 py-4 bg-white/10 hover:bg-white/20 text-white rounded-2xl font-bold transition-all"
            >
              Cancel
            </button>
            <button 
              onClick={handleUpload}
              disabled={isUploading}
              className="flex-[2] py-4 bg-indigo-500 hover:bg-indigo-600 disabled:opacity-50 text-white rounded-2xl font-bold shadow-xl shadow-indigo-500/20 transition-all flex items-center justify-center gap-2"
            >
              {isUploading ? <div className="w-5 h-5 border-2 border-white border-t-transparent rounded-full animate-spin"></div> : 'Post to Story'}
            </button>
          </div>
        </div>
      )}
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { Story } from '../../types';

interface StoryViewerProps {
  stories: Story[];
  onClose: () => void;
}

export const StoryViewer: React.FC<StoryViewerProps> = ({ stories, onClose }) => {
  const [currentIndex, setCurrentIndex] = useState(0);
  const [progress, setProgress] = useState(0);
  const story = stories[currentIndex];

  useEffect(() => {
    setProgress(0);
    const duration = story.mediaType === 'video' ? 10000 : 5000;
    const intervalTime = 50;
    const step = (intervalTime / duration) * 100;

    const timer = setInterval(() => {
      setProgress(prev => {
        if (prev >= 100) {
          clearInterval(timer);
          handleNext();
          return 100;
        }
        return prev + step;
      });
    }, intervalTime);

    return () => clearInterval(timer);
  }, [currentIndex]);

  const handleNext = () => {
    if (currentIndex < stories.length - 1) {
      setCurrentIndex(prev => prev + 1);
    } else {
      onClose();
    }
  };

  const handlePrev = () => {
    if (currentIndex > 0) {
      setCurrentIndex(prev => prev - 1);
    }
  };

  return (
    <div className="fixed inset-0 z-[110] bg-black flex flex-col">
      {/* Progress Bars */}
      <div className="flex gap-1.5 p-4 absolute top-0 inset-x-0 z-20">
        {stories.map((_, idx) => (
          <div key={idx} className="h-1 flex-1 bg-white/20 rounded-full overflow-hidden">
            <div 
              className="h-full bg-white transition-all duration-100 ease-linear"
              style={{ width: idx < currentIndex ? '100%' : idx === currentIndex ? `${progress}%` : '0%' }}
            />
          </div>
        ))}
      </div>

      {/* Header */}
      <div className="absolute top-8 inset-x-0 px-4 flex items-center justify-between z-20">
        <div className="flex items-center gap-3">
          <img src={story.userPhoto} className="w-10 h-10 rounded-full border border-white/20" alt="" />
          <div>
            <h4 className="text-white font-bold text-sm">{story.userName}</h4>
            <span className="text-white/60 text-[10px] uppercase font-bold tracking-widest">
              {new Date(story.timestamp).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
            </span>
          </div>
        </div>
        <button onClick={onClose} className="p-2 text-white/70 hover:text-white transition-colors">
          <svg className="w-8 h-8" fill="none" stroke="currentColor" viewBox="0 0 24 24">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M6 18L18 6M6 6l12 12" />
          </svg>
        </button>
      </div>

      {/* Content */}
      <div className="flex-1 flex items-center justify-center relative">
        <div className="absolute inset-y-0 left-0 w-1/4 z-30" onClick={handlePrev} />
        <div className="absolute inset-y-0 right-0 w-1/4 z-30" onClick={handleNext} />

        {story.mediaType === 'video' ? (
          <video src={story.mediaUrl} className="max-h-full w-full object-contain" autoPlay muted playsInline />
        ) : (
          <img src={story.mediaUrl} className="max-h-full w-full object-contain shadow-2xl" alt="" />
        )}

        {story.caption && (
          <div className="absolute bottom-12 inset-x-0 p-8 text-center bg-gradient-to-t from-black/80 via-black/40 to-transparent">
            <p className="text-white text-lg font-medium drop-shadow-lg">{story.caption}</p>
          </div>
        )}
      </div>
    </div>
  );
};

