    status: 'sent',
    storyContext: {
      storyId: story.id,
      mediaUrl: story.mediaUrl,
      mediaType: story.mediaType
    }
  };
  messages.push(newMessage);
  if (messages.length > 50) messages.shift(); // Keep history lean
  saveLocal(STORAGE_KEY_MESSAGES, messages);
  return newMessage;
};

