import React, { useEffect, useState } from 'react';
import { User, Story } from '../../types';
import { getStories } from '../../firebase';

interface StoryBarProps {
  currentUser: User;
  onUploadClick: () => void;
  onStoryClick: (stories: Story[]) => void;
}

export const StoryBar: React.FC<StoryBarProps> = ({ currentUser, onUploadClick, onStoryClick }) => {
  const [stories, setStories] = useState<Story[]>([]);

  useEffect(() => {
    const loadStories = async () => {
      const data = await getStories();
      setStories(data);
    };
    loadStories();

    // Refresh every 30 seconds
    const interval = setInterval(loadStories, 30000);
    return () => clearInterval(interval);
  }, []);

  // Group stories by user using a robust forEach loop
  const userStoriesMap: Record<string, Story[]> = {};
  stories.forEach(story => {
    if (!userStoriesMap[story.userId]) {
      userStoriesMap[story.userId] = [];
    }
    userStoriesMap[story.userId].push(story);
  });

  const myStories = userStoriesMap[currentUser.uid] || [];
  const otherUserIds = Object.keys(userStoriesMap).filter(id => id !== currentUser.uid);

  return (
    <div className="flex items-center gap-4 px-4 py-3 overflow-x-auto no-scrollbar bg-white dark:bg-slate-900 border-b border-slate-100 dark:border-slate-800">
      {/* My Status */}
      <div className="flex flex-col items-center gap-1 shrink-0">
        <div className="relative cursor-pointer group" onClick={myStories.length > 0 ? () => onStoryClick(myStories) : onUploadClick}>
          <div className={`w-16 h-16 rounded-full p-[3px] ${myStories.length > 0 ? 'bg-gradient-to-tr from-indigo-500 to-pink-500' : ''}`}>
            <img 
              src={currentUser.photoURL} 
              alt="My Status" 
              className="w-full h-full rounded-full object-cover border-2 border-white dark:border-slate-900"
            />
          </div>
          <button 
            onClick={(e) => { e.stopPropagation(); onUploadClick(); }}
            className="absolute bottom-0 right-0 w-6 h-6 bg-indigo-500 text-white rounded-full flex items-center justify-center border-2 border-white dark:border-slate-900 shadow-md group-hover:scale-110 transition-transform"
          >
            <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M12 6v6m0 0v6m0-6h6m-6 0H6" />
            </svg>
          </button>
        </div>
        <span className="text-[11px] font-semibold text-slate-500 dark:text-slate-400">My Status</span>
      </div>

      {/* Others' Stories */}
      {otherUserIds.map(userId => {
        const userStories = userStoriesMap[userId];
        const firstStory = userStories[0];
        return (
          <div key={userId} className="flex flex-col items-center gap-1 shrink-0">
            <div className="cursor-pointer" onClick={() => onStoryClick(userStories)}>
              <div className="w-16 h-16 rounded-full bg-gradient-to-tr from-green-400 to-blue-500 p-[3px]">
                <img 
                  src={firstStory.userPhoto} 
                  alt={firstStory.userName} 
                  className="w-full h-full rounded-full object-cover border-2 border-white dark:border-slate-900"
                />
              </div>
            </div>
            <span className="text-[11px] font-semibold text-slate-500 dark:text-slate-400 truncate w-16 text-center">
              {firstStory.userName.split(' ')[0]}
            </span>
          </div>
        );
      })}
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { Story, User } from '../../types';
import { likeStory, sendStoryReply } from '../../firebase';

interface StoryViewerProps {
  stories: Story[];
  currentUser: User;
  onClose: () => void;
}

export const StoryViewer: React.FC<StoryViewerProps> = ({ stories, currentUser, onClose }) => {
  const [currentIndex, setCurrentIndex] = useState(0);
  const [progress, setProgress] = useState(0);
  const [replyText, setReplyText] = useState('');
  const [isLiked, setIsLiked] = useState(false);
  const [showHeartAnim, setShowHeartAnim] = useState(false);
  const [isPaused, setIsPaused] = useState(false);

  const story = stories[currentIndex];

  useEffect(() => {
    setIsLiked(story.likes?.includes(currentUser.uid) || false);
    setProgress(0);
    setReplyText('');

    if (isPaused) return;

    const duration = story.mediaType === 'video' ? 10000 : 5000;
    const intervalTime = 50;
    const step = (intervalTime / duration) * 100;

    const timer = setInterval(() => {
      setProgress(prev => {
        if (prev >= 100) {
          clearInterval(timer);
          handleNext();
          return 100;
        }
        return prev + step;
      });
    }, intervalTime);

    return () => clearInterval(timer);
  }, [currentIndex, isPaused]);

  const handleNext = () => {
    if (currentIndex < stories.length - 1) {
      setCurrentIndex(prev => prev + 1);
    } else {
      onClose();
    }
  };

  const handlePrev = () => {
    if (currentIndex > 0) {
      setCurrentIndex(prev => prev - 1);
    }
  };

  const handleLike = async () => {
    if (!isLiked) {
      setShowHeartAnim(true);
      setTimeout(() => setShowHeartAnim(false), 800);
    }
    setIsLiked(!isLiked);
    await likeStory(story.id, currentUser.uid);
  };

  const handleReply = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!replyText.trim()) return;

    const text = replyText.trim();
    setReplyText('');

    // Resume progress after reply
    setIsPaused(false);

    await sendStoryReply(story.userId, currentUser.uid, text, story);

    // Brief visual confirmation
    alert("Reply sent!");
    handleNext();
  };

  return (
    <div className="fixed inset-0 z-[110] bg-black flex flex-col">
      {/* Progress Bars */}
      <div className="flex gap-1.5 p-4 absolute top-0 inset-x-0 z-20">
        {stories.map((_, idx) => {
          const barWidth = idx < currentIndex ? '100%' : idx === currentIndex ? progress + '%' : '0%';
          return (
            <div key={idx} className="h-1 flex-1 bg-white/20 rounded-full overflow-hidden">
              <div 
                className="h-full bg-white transition-all duration-100 ease-linear"
                style={{ width: barWidth }}
              />
            </div>
          );
        })}
      </div>

      {/* Header */}
      <div className="absolute top-8 inset-x-0 px-4 flex items-center justify-between z-20">
        <div className="flex items-center gap-3">
          <img src={story.userPhoto} className="w-10 h-10 rounded-full border border-white/20" alt="" />
          <div>
            <h4 className="text-white font-bold text-sm">{story.userName}</h4>
            <span className="text-white/60 text-[10px] uppercase font-bold tracking-widest">
              {new Date(story.timestamp).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
            </span>
          </div>
        </div>
        <button onClick={onClose} className="p-2 text-white/70 hover:text-white transition-colors">
          <svg className="w-8 h-8" fill="none" stroke="currentColor" viewBox="0 0 24 24">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M6 18L18 6M6 6l12 12" />
          </svg>
        </button>
      </div>

      {/* Content */}
      <div className="flex-1 flex items-center justify-center relative select-none">
        {/* Navigation Areas */}
        <div className="absolute inset-y-0 left-0 w-1/4 z-30 cursor-pointer" onClick={handlePrev} />
        <div className="absolute inset-y-0 right-0 w-1/4 z-30 cursor-pointer" onClick={handleNext} />

        {/* Heart Animation Overlay */}
        {showHeartAnim && (
          <div className="absolute z-40 animate-ping">
            <svg className="w-32 h-32 text-red-500" fill="currentColor" viewBox="0 0 24 24">
              <path d="M12 21.35l-1.45-1.32C5.4 15.36 2 12.28 2 8.5 2 5.42 4.42 3 7.5 3c1.74 0 3.41.81 4.5 2.09C13.09 3.81 14.76 3 16.5 3 19.58 3 22 5.42 22 8.5c0 3.78-3.4 6.86-8.55 11.54L12 21.35z" />
            </svg>
          </div>
        )}

        {story.mediaType === 'video' ? (
          <video src={story.mediaUrl} className="max-h-full w-full object-contain" autoPlay muted playsInline />
        ) : (
          <img 
            src={story.mediaUrl} 
            className="max-h-full w-full object-contain shadow-2xl transition-transform active:scale-95" 
            alt="" 
            onDoubleClick={handleLike}
          />
        )}

        {/* Caption */}
        {story.caption && (
          <div className="absolute bottom-24 inset-x-0 p-8 text-center bg-gradient-to-t from-black/80 via-black/40 to-transparent z-10">
            <p className="text-white text-lg font-medium drop-shadow-lg">{story.caption}</p>
          </div>
        )}
      </div>

      {/* Footer (Reply & Like) */}
      <div className="p-4 md:p-6 glass bg-black/40 border-t border-white/10 z-50">
        <div className="max-w-xl mx-auto flex items-center gap-4">
          <form onSubmit={handleReply} className="flex-1 flex items-center gap-3">
            <input 
              type="text"
              placeholder="Reply to story..."
              value={replyText}
              onFocus={() => setIsPaused(true)}
              onBlur={() => setIsPaused(false)}
              onChange={(e) => setReplyText(e.target.value)}
              className="flex-1 bg-white/10 border border-white/20 rounded-full px-5 py-2.5 text-white placeholder-white/50 focus:outline-none focus:ring-2 focus:ring-white/30 transition-all text-sm"
            />
            {replyText.trim() && (
              <button type="submit" className="text-white bg-indigo-500 p-2.5 rounded-full hover:bg-indigo-600 transition-all active:scale-90">
                <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 19l9 2-9-18-9 18 9-2zm0 0v-8" />
                </svg>
              </button>
            )}
          </form>

          <button 
            onClick={handleLike}
            className={`p-2.5 rounded-full transition-all active:scale-125 ${isLiked ? 'text-red-500 scale-110' : 'text-white/70 hover:text-white'}`}
          >
            <svg className={`w-7 h-7 ${isLiked ? 'fill-current' : 'fill-none stroke-current'}`} strokeWidth="2" viewBox="0 0 24 24">
              <path d="M12 21.35l-1.45-1.32C5.4 15.36 2 12.28 2 8.5 2 5.42 4.42 3 7.5 3c1.74 0 3.41.81 4.5 2.09C13.09 3.81 14.76 3 16.5 3 19.58 3 22 5.42 22 8.5c0 3.78-3.4 6.86-8.55 11.54L12 21.35z" />
            </svg>
          </button>
        </div>
      </div>
    </div>
  );
};

import React, { useState, useRef, useEffect } from 'react';
import { User, Story } from '../../types';
import { addStory } from '../../firebase';

interface StoryUploadProps {
  currentUser: User;
  onClose: () => void;
}

export const StoryUpload: React.FC<StoryUploadProps> = ({ currentUser, onClose }) => {
  const [file, setFile] = useState<File | null>(null);
  const [preview, setPreview] = useState<string | null>(null);
  const [caption, setCaption] = useState('');
  const [isUploading, setIsUploading] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  // Cleanup object URL to avoid memory leaks
  useEffect(() => {
    return () => {
      if (preview && preview.startsWith('blob:')) {
        URL.revokeObjectURL(preview);
      }
    };
  }, [preview]);

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const selected = e.target.files?.[0];
    if (selected) {
      // Basic size check (approx 1.5MB) for local storage stability
      if (selected.size > 1.5 * 1024 * 1024) {
        alert("Please choose a smaller image (under 1.5MB) to prevent storage limits.");
        if (e.target) e.target.value = '';
        return;
      }

      setFile(selected);
      // Use createObjectURL for instant preview instead of slow FileReader
      const objectUrl = URL.createObjectURL(selected);
      setPreview(objectUrl);

      // Reset input value so the same file can be selected again if needed
      if (e.target) e.target.value = '';
    }
  };

  const handleUpload = async () => {
    if (!file) return;
    setIsUploading(true);

    try {
      // Convert file to Base64 only during the final save step for persistence
      const base64Data = await new Promise<string>((resolve, reject) => {
        const reader = new FileReader();
        reader.onload = () => resolve(reader.result as string);
        reader.onerror = reject;
        reader.readAsDataURL(file);
      });

      const newStory: Story = {
        id: crypto.randomUUID(),
        userId: currentUser.uid,
        userName: currentUser.name,
        userPhoto: currentUser.photoURL,
        mediaUrl: base64Data,
        mediaType: file.type.startsWith('video/') ? 'video' : 'image',
        caption: caption,
        timestamp: Date.now()
      };

      await addStory(newStory);
      onClose();
    } catch (e) {
      console.error("Upload error:", e);
      alert("Something went wrong. The file might be too large for browser storage.");
    } finally {
      setIsUploading(false);
    }
  };

  return (
    <div className="fixed inset-0 z-[100] bg-slate-950 flex flex-col items-center justify-center p-4 animate-in fade-in duration-300">
      <button onClick={onClose} className="absolute top-6 left-6 p-3 text-white hover:bg-white/10 rounded-full transition-all">
        <svg className="w-8 h-8" fill="none" stroke="currentColor" viewBox="0 0 24 24">
          <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M6 18L18 6M6 6l12 12" />
        </svg>
      </button>

      {!preview ? (
        <div className="text-center space-y-6 animate-in zoom-in-95 duration-300">
          <div className="w-24 h-24 bg-white/10 rounded-full flex items-center justify-center mx-auto mb-6">
            <svg className="w-12 h-12 text-white/40" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M4 16l4.586-4.586a2 2 0 012.828 0L16 16m-2-2l1.586-1.586a2 2 0 012.828 0L20 14m-6-6h.01M6 20h12a2 2 0 002-2V6a2 2 0 00-2-2H6a2 2 0 00-2 2v12a2 2 0 002 2z" />
            </svg>
          </div>
          <h2 className="text-2xl font-bold text-white">Add to Story</h2>
          <p className="text-white/40 max-w-xs mx-auto text-sm">
            Share a photo with your contacts.<br/>
            <span className="text-indigo-400 font-bold">Tip: Use small files for best experience.</span>
          </p>
          <button 
            onClick={() => fileInputRef.current?.click()}
            className="px-8 py-4 bg-indigo-500 hover:bg-indigo-600 text-white rounded-2xl font-bold shadow-xl shadow-indigo-500/20 active:scale-95 transition-all"
          >
            Choose from Gallery
          </button>
          <input 
            type="file" 
            ref={fileInputRef} 
            onChange={handleFileChange} 
            accept="image/*,video/*" 
            className="hidden" 
          />
        </div>
      ) : (
        <div className="w-full max-w-md flex flex-col gap-6 animate-in slide-in-from-bottom-10 duration-500">
          <div className="relative aspect-[9/16] bg-black rounded-3xl overflow-hidden shadow-2xl ring-1 ring-white/10">
            {file?.type.startsWith('video/') ? (
              <video src={preview} className="w-full h-full object-contain" autoPlay muted loop playsInline />
            ) : (
              <img src={preview} alt="Preview" className="w-full h-full object-contain" />
            )}

            <div className="absolute bottom-0 inset-x-0 p-6 bg-gradient-to-t from-black/80 to-transparent">
               <textarea 
                value={caption}
                onChange={(e) => setCaption(e.target.value)}
                placeholder="Add a caption..."
                className="w-full bg-white/10 backdrop-blur-md border border-white/20 rounded-2xl p-4 text-white placeholder-white/40 focus:ring-2 focus:ring-indigo-500 outline-none resize-none transition-all"
                rows={2}
              />
            </div>
          </div>

          <div className="flex gap-4">
            <button 
              onClick={() => { setFile(null); setPreview(null); }}
              className="flex-1 py-4 bg-white/10 hover:bg-white/20 text-white rounded-2xl font-bold transition-all"
            >
              Cancel
            </button>
            <button 
              onClick={handleUpload}
              disabled={isUploading}
              className="flex-[2] py-4 bg-indigo-500 hover:bg-indigo-600 disabled:opacity-50 text-white rounded-2xl font-bold shadow-xl shadow-indigo-500/20 transition-all flex items-center justify-center gap-2"
            >
              {isUploading ? (
                <div className="w-5 h-5 border-2 border-white border-t-transparent rounded-full animate-spin"></div>
              ) : (
                'Post to Story'
              )}
            </button>
          </div>
        </div>
      )}
    </div>
  );
};

