};

import React, { useState, useRef, useEffect } from 'react';
import { User, Story } from '../../types';
import { addStory } from '../../firebase';

interface StoryUploadProps {
  currentUser: User;
  onClose: () => void;
}

export const StoryUpload: React.FC<StoryUploadProps> = ({ currentUser, onClose }) => {
  const [file, setFile] = useState<File | null>(null);
  const [preview, setPreview] = useState<string | null>(null);
  const [mediaType, setMediaType] = useState<'image' | 'video' | null>(null);
  const [caption, setCaption] = useState('');
  const [isUploading, setIsUploading] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  // Cleanup object URL to avoid memory leaks
  useEffect(() => {
    return () => {
      if (preview && preview.startsWith('blob:')) {
        URL.revokeObjectURL(preview);
      }
    };
  }, [preview]);

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const selected = e.target.files?.[0];
    if (!selected) return;

    // Strict Size limit for videos in local storage (approx 4MB max for safety)
    const limit = selected.type.startsWith('video/') ? 4 * 1024 * 1024 : 2 * 1024 * 1024;

    if (selected.size > limit) {
      alert(`File too large! Max ${selected.type.startsWith('video/') ? '4MB for video' : '2MB for image'}. Large files can't be saved in browser memory.`);
      e.target.value = '';
      return;
    }

    const isVideo = selected.type.startsWith('video/');
    setMediaType(isVideo ? 'video' : 'image');
    setFile(selected);

    // Revoke old preview if it exists
    if (preview && preview.startsWith('blob:')) {
      URL.revokeObjectURL(preview);
    }

    const objectUrl = URL.createObjectURL(selected);
    setPreview(objectUrl);

    // Clear input so same file can be selected again
    e.target.value = '';
  };

  const handleUpload = async () => {
    if (!file || !mediaType) return;
    setIsUploading(true);

    try {
      // Convert to Base64 for persistence in our mock DB (LocalStorage)
      const base64Data = await new Promise<string>((resolve, reject) => {
        const reader = new FileReader();
        reader.onload = () => resolve(reader.result as string);
        reader.onerror = () => reject(new Error("Failed to read file"));
        reader.readAsDataURL(file);
      });

      const newStory: Story = {
        id: crypto.randomUUID(),
        userId: currentUser.uid,
        userName: currentUser.name,
        userPhoto: currentUser.photoURL,
        mediaUrl: base64Data,
        mediaType: mediaType,
        caption: caption,
        timestamp: Date.now()
      };

      await addStory(newStory);
      onClose();
    } catch (e) {
      console.error("Upload error:", e);
      alert("Error saving story. The video might be too long or high-quality for browser storage.");
    } finally {
      setIsUploading(false);
    }
  };

  return (
    <div className="fixed inset-0 z-[100] bg-slate-950 flex flex-col items-center justify-center p-4 overflow-hidden">
      {/* Hidden File Input */}
      <input 
        type="file" 
        ref={fileInputRef} 
        onChange={handleFileChange} 
        accept="image/*,video/*" 
        className="hidden" 
      />

      {/* Close Button */}
      <button 
        onClick={onClose} 
        className="absolute top-6 left-6 p-3 text-white hover:bg-white/10 rounded-full transition-all z-[110]"
      >
        <svg className="w-8 h-8" fill="none" stroke="currentColor" viewBox="0 0 24 24">
          <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M6 18L18 6M6 6l12 12" />
        </svg>
      </button>

      {!preview ? (
        <div className="text-center space-y-6 animate-in zoom-in-95 duration-300">
          <div className="w-24 h-24 bg-indigo-500/20 rounded-full flex items-center justify-center mx-auto mb-6">
            <svg className="w-12 h-12 text-indigo-400" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M15 10l4.553-2.276A1 1 0 0121 8.618v6.764a1 1 0 01-1.447.894L15 14M5 18h8a2 2 0 002-2V8a2 2 0 00-2-2H5a2 2 0 00-2 2v8a2 2 0 002 2z" />
            </svg>
          </div>
          <h2 className="text-2xl font-bold text-white">Share Video or Photo</h2>
          <p className="text-white/40 max-w-xs mx-auto text-sm">
            Share a quick moment with your friends. 
            <br/><span className="text-orange-400 mt-2 block font-medium">Keep videos under 10 seconds for best results.</span>
          </p>
          <button 
            onClick={() => fileInputRef.current?.click()}
            className="px-8 py-4 bg-indigo-500 hover:bg-indigo-600 text-white rounded-2xl font-bold shadow-xl shadow-indigo-500/20 active:scale-95 transition-all"
          >
            Open Gallery
          </button>
        </div>
      ) : (
        <div className="w-full max-w-md flex flex-col gap-4 animate-in slide-in-from-bottom-10 duration-500">
          <div className="relative aspect-[9/16] bg-black rounded-3xl overflow-hidden shadow-2xl ring-1 ring-white/10">
            {mediaType === 'video' ? (
              <video 
                key={preview} // Important: Force re-load when preview changes
                src={preview} 
                className="w-full h-full object-contain" 
                autoPlay 
                muted 
                loop 
                playsInline 
              />
            ) : (
              <img src={preview} alt="Preview" className="w-full h-full object-contain" />
            )}

            <div className="absolute bottom-0 inset-x-0 p-6 bg-gradient-to-t from-black/90 via-black/40 to-transparent">
               <textarea 
                value={caption}
                onChange={(e) => setCaption(e.target.value)}
                placeholder="Add a caption..."
                className="w-full bg-white/10 backdrop-blur-md border border-white/20 rounded-2xl p-4 text-white placeholder-white/40 focus:ring-2 focus:ring-indigo-500 outline-none resize-none transition-all text-sm"
                rows={2}
              />
            </div>
          </div>

          <div className="flex gap-4">
            <button 
              onClick={() => { setFile(null); setPreview(null); setMediaType(null); }}
              className="flex-1 py-4 bg-white/10 hover:bg-white/20 text-white rounded-2xl font-bold transition-all text-sm"
            >
              Back
            </button>
            <button 
              onClick={handleUpload}
              disabled={isUploading}
              className="flex-[2] py-4 bg-indigo-500 hover:bg-indigo-600 disabled:opacity-50 text-white rounded-2xl font-bold shadow-xl shadow-indigo-500/20 transition-all flex items-center justify-center gap-2 text-sm"
            >
              {isUploading ? (
                <>
                  <div className="w-4 h-4 border-2 border-white border-t-transparent rounded-full animate-spin"></div>
                  <span>Saving...</span>
                </>
              ) : (
                'Share to Story'
              )}
            </button>
          </div>
        </div>
      )}
    </div>
  );
};

import React, { useState, useRef } from 'react';
import { User } from '../../types';
import { useAuth } from '../../hooks/useAuth';
import { updateProfile } from '../../firebase';

interface ProfilePanelProps {
  user: User;
  onClose: () => void;
  toggleDarkMode: () => void;
  isDarkMode: boolean;
}

export const ProfilePanel: React.FC<ProfilePanelProps> = ({ user, onClose, toggleDarkMode, isDarkMode }) => {
  const { logout } = useAuth();
  const [isEditing, setIsEditing] = useState(false);
  const [name, setName] = useState(user.name);
  const [bio, setBio] = useState(user.bio || 'Available');
  const [photoPreview, setPhotoPreview] = useState(user.photoURL);
  const [isSaving, setIsSaving] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const handlePhotoChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      if (file.size > 1 * 1024 * 1024) {
        alert("Photo is too large. Please use an image under 1MB.");
        return;
      }
      const reader = new FileReader();
      reader.onloadend = () => {
        setPhotoPreview(reader.result as string);
      };
      reader.readAsDataURL(file);
    }
  };

  const handleSave = async () => {
    setIsSaving(true);
    try {
      await updateProfile(user, {
        name,
        bio,
        photoURL: photoPreview
      });
      setIsEditing(false);
    } catch (err) {
      alert("Failed to update profile.");
    } finally {
      setIsSaving(false);
    }
  };

  const handleResetData = () => {
    if (window.confirm("Reset all data? This will clear everything.")) {
      localStorage.clear();
      window.location.reload();
    }
  };

  return (
    <div className="fixed inset-0 z-50 flex justify-end">
      <div className="absolute inset-0 bg-slate-900/60 backdrop-blur-sm" onClick={onClose}></div>
      <div className="relative w-full max-w-sm h-full bg-white dark:bg-slate-900 shadow-2xl flex flex-col animate-slide-left">
