              </div>
            ) : (
              <div className="w-full">
                <h3 className="text-xl font-bold">{user.name}</h3>
                <p className="text-sm text-slate-500 italic mt-1">"{user.bio || 'Available'}"</p>
                <button onClick={() => setIsEditing(true)} className="mt-4 text-xs font-bold text-indigo-500 uppercase tracking-widest border border-indigo-500/30 px-4 py-2 rounded-full hover:bg-indigo-500/10 transition-all">
