  { id: '3', participants: ['current', 'user_3'], updatedAt: Date.now(), lastMessage: { text: 'Check out this attachment!', senderId: 'user_3', timestamp: Date.now() - 1000 * 60 * 60 * 24 } },
];

const MOCK_USERS: Record<string, any> = {
  'user_1': { uid: 'user_1', name: 'Sarah Wilson', photoURL: 'https://picsum.photos/seed/sarah/200', status: 'online', bio: 'Living my best life ✨' },
  'user_2': { uid: 'user_2', name: 'Alex Rivers', photoURL: 'https://picsum.photos/seed/alex/200', status: 'offline', bio: 'Coffee lover | Developer' },
  'user_3': { uid: 'user_3', name: 'Jordan Sparks', photoURL: 'https://picsum.photos/seed/jordan/200', status: 'online', bio: 'Always wandering 🌍' },
};

export const Sidebar: React.FC<SidebarProps> = ({ 
  currentUser, 
  onChatSelect, 
  onProfileClick, 
  activeChatId, 
  onStoryUpload, 
  onStoryView,
  onUserClick
}) => {
  const [search, setSearch] = useState('');

  const filteredChats = useMemo(() => {
    return MOCK_CHATS.filter(chat => {
      const otherId = chat.participants.find(p => p !== 'current') || '';
      const user = MOCK_USERS[otherId];
      return user.name.toLowerCase().includes(search.toLowerCase());
    });
  }, [search]);

  const formatTime = (ts: number) => {
    const now = Date.now();
    const diff = now - ts;
    if (diff < 24 * 60 * 60 * 1000) {
      return new Date(ts).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
    }
    return new Date(ts).toLocaleDateString([], { month: 'short', day: 'numeric' });
  };

  return (
    <div className="w-full h-full flex flex-col bg-white dark:bg-slate-900 z-10 transition-colors">
      {/* Header */}
      <div className="p-4 flex items-center justify-between border-b border-slate-100 dark:border-slate-800">
