const STORAGE_KEY_USERS = 'gemini_chat_db_users';
const STORAGE_KEY_SESSION = 'chat_session';
const STORAGE_KEY_STORIES = 'gemini_chat_db_stories';
const STORAGE_KEY_MESSAGES = 'gemini_chat_db_messages';

// Helper to interact with LocalStorage with Advanced Quota Management
const getLocal = (key: string) => JSON.parse(localStorage.getItem(key) || '[]');

const saveLocal = (key: string, data: any) => {
  try {
    localStorage.setItem(key, JSON.stringify(data));
  } catch (e) {
    if (e instanceof DOMException && (e.code === 22 || e.code === 1014 || e.name === 'QuotaExceededError')) {
      console.warn('Storage quota exceeded. Initiating Smart Purge...');

      // 1. Purge half of the oldest stories first
      const stories = getLocal(STORAGE_KEY_STORIES);
      if (stories.length > 0) {
        // Sort by timestamp and remove oldest 50%
        stories.sort((a: any, b: any) => a.timestamp - b.timestamp);
        const remainingStories = stories.slice(Math.floor(stories.length / 2));
        localStorage.setItem(STORAGE_KEY_STORIES, JSON.stringify(remainingStories));
      }

      // 2. Keep only most recent 10 messages
      const messages = getLocal(STORAGE_KEY_MESSAGES);
      if (messages.length > 10) {
        localStorage.setItem(STORAGE_KEY_MESSAGES, JSON.stringify(messages.slice(-10)));
      }

      // 3. Try to save again
      try {
        localStorage.setItem(key, JSON.stringify(data));
        console.log('Smart Purge successful. Data saved.');
      } catch (retryError) {
        // If still fails, clear ALL stories as a last resort
        console.error('Secondary storage failure. Clearing all media...');
        localStorage.removeItem(STORAGE_KEY_STORIES);
        try {
          localStorage.setItem(key, JSON.stringify(data));
        } catch (finalError) {
          throw new Error("Critical storage failure: The file is physically too large for this browser's memory.");
        }
      }
    } else {
      throw e;
    }
  }
};

