import React, { useState, useEffect } from 'react';
import { Story, User } from '../../types';
import { likeStory, sendStoryReply } from '../../firebase';

interface StoryViewerProps {
  stories: Story[];
  currentUser: User;
  onClose: () => void;
}

export const StoryViewer: React.FC<StoryViewerProps> = ({ stories, currentUser, onClose }) => {
  const [currentIndex, setCurrentIndex] = useState(0);
  const [progress, setProgress] = useState(0);
  const [replyText, setReplyText] = useState('');
  const [isLiked, setIsLiked] = useState(false);
  const [showHeartAnim, setShowHeartAnim] = useState(false);
  const [isPaused, setIsPaused] = useState(false);

  const story = stories[currentIndex];

  useEffect(() => {
    setIsLiked(story.likes?.includes(currentUser.uid) || false);
    setProgress(0);
    setReplyText('');

    if (isPaused) return;

    const duration = story.mediaType === 'video' ? 10000 : 5000;
    const intervalTime = 50;
    const step = (intervalTime / duration) * 100;

    const timer = setInterval(() => {
      setProgress(prev => {
        if (prev >= 100) {
          clearInterval(timer);
          handleNext();
          return 100;
        }
        return prev + step;
      });
    }, intervalTime);

    return () => clearInterval(timer);
  }, [currentIndex, isPaused]);

  const handleNext = () => {
    if (currentIndex < stories.length - 1) {
      setCurrentIndex(prev => prev + 1);
    } else {
      onClose();
    }
  };

  const handlePrev = () => {
    if (currentIndex > 0) {
      setCurrentIndex(prev => prev - 1);
    }
  };

  const handleLike = async () => {
    if (!isLiked) {
      setShowHeartAnim(true);
      setTimeout(() => setShowHeartAnim(false), 800);
    }
    setIsLiked(!isLiked);
    await likeStory(story.id, currentUser.uid);
  };

  const handleReply = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!replyText.trim()) return;

    const text = replyText.trim();
    setReplyText('');

    setIsPaused(false);

    await sendStoryReply(story.userId, currentUser.uid, text, story);

    alert("Reply sent!");
    handleNext();
  };

  return (
    <div className="fixed inset-0 z-[110] bg-black flex flex-col">
      {/* Progress Bars */}
      <div className="flex gap-1.5 p-4 absolute top-0 inset-x-0 z-20">
        {stories.map((_, idx) => {
          const barWidth = idx < currentIndex ? '100%' : idx === currentIndex ? progress + '%' : '0%';
          return (
            <div key={idx} className="h-1 flex-1 bg-white/20 rounded-full overflow-hidden">
              <div 
                className="h-full bg-white transition-all duration-100 ease-linear"
                style={{ width: barWidth }}
              />
            </div>
          );
        })}
      </div>

      {/* Header */}
      <div className="absolute top-8 inset-x-0 px-4 flex items-center justify-between z-20">
        <div className="flex items-center gap-3">
          <img src={story.userPhoto} className="w-10 h-10 rounded-full border border-white/20" alt="" />
          <div>
            <h4 className="text-white font-bold text-sm">{story.userName}</h4>
            <span className="text-white/60 text-[10px] uppercase font-bold tracking-widest">
              {new Date(story.timestamp).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
            </span>
          </div>
        </div>
        <button onClick={onClose} className="p-2 text-white/70 hover:text-white transition-colors">
          <svg className="w-8 h-8" fill="none" stroke="currentColor" viewBox="0 0 24 24">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M6 18L18 6M6 6l12 12" />
          </svg>
        </button>
      </div>

      {/* Content */}
      <div className="flex-1 flex items-center justify-center relative select-none">
        <div className="absolute inset-y-0 left-0 w-1/4 z-30 cursor-pointer" onClick={handlePrev} />
        <div className="absolute inset-y-0 right-0 w-1/4 z-30 cursor-pointer" onClick={handleNext} />

        {showHeartAnim && (
          <div className="absolute z-40 animate-ping">
            <svg className="w-32 h-32 text-red-500" fill="currentColor" viewBox="0 0 24 24">
              <path d="M12 21.35l-1.45-1.32C5.4 15.36 2 12.28 2 8.5 2 5.42 4.42 3 7.5 3c1.74 0 3.41.81 4.5 2.09C13.09 3.81 14.76 3 16.5 3 19.58 3 22 5.42 22 8.5c0 3.78-3.4 6.86-8.55 11.54L12 21.35z" />
            </svg>
          </div>
        )}

        {story.mediaType === 'video' ? (
          <video 
            src={story.mediaUrl} 
            className="max-h-full w-full object-contain" 
            autoPlay 
            playsInline 
          />
        ) : (
          <img 
            src={story.mediaUrl} 
            className="max-h-full w-full object-contain shadow-2xl transition-transform active:scale-95" 
            alt="" 
            onDoubleClick={handleLike}
          />
        )}

        {story.caption && (
          <div className="absolute bottom-24 inset-x-0 p-8 text-center bg-gradient-to-t from-black/80 via-black/40 to-transparent z-10">
            <p className="text-white text-lg font-medium drop-shadow-lg">{story.caption}</p>
          </div>
        )}
      </div>

      {/* Footer */}
      <div className="p-4 md:p-6 glass bg-black/40 border-t border-white/10 z-50">
        <div className="max-w-xl mx-auto flex items-center gap-4">
          <form onSubmit={handleReply} className="flex-1 flex items-center gap-3">
            <input 
              type="text"
              placeholder="Reply to story..."
              value={replyText}
              onFocus={() => setIsPaused(true)}
              onBlur={() => setIsPaused(false)}
              onChange={(e) => setReplyText(e.target.value)}
              className="flex-1 bg-white/10 border border-white/20 rounded-full px-5 py-2.5 text-white placeholder-white/50 focus:outline-none focus:ring-2 focus:ring-white/30 transition-all text-sm"
            />
            {replyText.trim() && (
              <button type="submit" className="text-white bg-indigo-500 p-2.5 rounded-full hover:bg-indigo-600 transition-all active:scale-90">
                <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 19l9 2-9-18-9 18 9-2zm0 0v-8" />
                </svg>
              </button>
            )}
          </form>

          <button 
            onClick={handleLike}
            className={`p-2.5 rounded-full transition-all active:scale-125 ${isLiked ? 'text-red-500 scale-110' : 'text-white/70 hover:text-white'}`}
          >
            <svg className={`w-7 h-7 ${isLiked ? 'fill-current' : 'fill-none stroke-current'}`} strokeWidth="2" viewBox="0 0 24 24">
              <path d="M12 21.35l-1.45-1.32C5.4 15.36 2 12.28 2 8.5 2 5.42 4.42 3 7.5 3c1.74 0 3.41.81 4.5 2.09C13.09 3.81 14.76 3 16.5 3 19.58 3 22 5.42 22 8.5c0 3.78-3.4 6.86-8.55 11.54L12 21.35z" />
            </svg>
          </button>
        </div>
      </div>
    </div>
  );
};

