                </svg>
              </div>
              <span className="text-[10px] font-bold uppercase tracking-widest">Gemini AI</span>
            </div>
          )}

          {/* Reply Context */}
          {message.replyContext && (
            <div className={`mb-2 p-2 rounded-xl text-xs border-l-4 ${isOwn ? 'bg-indigo-700/50 border-indigo-300' : 'bg-slate-100 dark:bg-slate-700 border-indigo-500'}`}>
