              <p className="opacity-70 line-clamp-2 italic">{message.replyContext.text}</p>
            </div>
          )}

          {message.type === 'story_reply' && message.storyContext && (
            <div className={`mb-2 p-2 rounded-xl flex gap-2 border border-white/20 ${isOwn ? 'bg-indigo-700/50' : 'bg-slate-100 dark:bg-slate-700'}`}>
              <div className="w-12 h-16 shrink-0 bg-black/20 rounded overflow-hidden">
                {message.storyContext.mediaType === 'video' ? (
                  <video src={message.storyContext.mediaUrl} className="w-full h-full object-cover" />
                ) : (
                  <img src={message.storyContext.mediaUrl} className="w-full h-full object-cover" />
