import React, { useState, useMemo, useEffect } from 'react';
import { User, Chat, Story } from '../../types';
import { StoryBar } from './StoryBar';
import { getAllUsers } from '../../firebase';

interface SidebarProps {
  currentUser: User;
  onChatSelect: (chat: Chat) => void;
  onProfileClick: () => void;
  activeChatId?: string;
  onStoryUpload: () => void;
  onStoryView: (stories: Story[]) => void;
  onUserClick: (user: User) => void;
}

// In a real app, this would come from a 'chats' collection in Firestore
const INITIAL_MOCK_CHATS: Chat[] = [
  { id: '1', participants: ['current', 'user_1'], updatedAt: Date.now(), lastMessage: { text: 'Hey, did you see the new update?', senderId: 'user_1', timestamp: Date.now() - 1000 * 60 * 5 } },
];

export const Sidebar: React.FC<SidebarProps> = ({ 
  currentUser, 
  onChatSelect, 
  onProfileClick, 
  activeChatId, 
  onStoryUpload, 
  onStoryView,
  onUserClick
}) => {
  const [search, setSearch] = useState('');
  const [allUsers, setAllUsers] = useState<User[]>([]);
  const [chats, setChats] = useState<Chat[]>(INITIAL_MOCK_CHATS);

  useEffect(() => {
    const fetchUsers = async () => {
      const users = await getAllUsers();
      // Filter out current user
      setAllUsers(users.filter((u: User) => u.uid !== currentUser.uid));
    };
    fetchUsers();
  }, [currentUser.uid]);

  // Combined search: Finds existing chats AND potential new contacts
  const searchResults = useMemo(() => {
    if (!search.trim()) return { chats, users: [] };

    const term = search.toLowerCase();

    // 1. Find users who match search term
    const matchedUsers = allUsers.filter(u => 
      u.name.toLowerCase().includes(term) || u.email.toLowerCase().includes(term)
    );

    // 2. Separate them into "People you've chatted with" and "New people"
    const existingChatUserIds = new Set(
      chats.flatMap(c => c.participants).filter(p => p !== 'current')
    );

    const filteredChats = chats.filter(chat => {
      const otherId = chat.participants.find(p => p !== 'current') || '';
      const user = allUsers.find(u => u.uid === otherId);
      return user?.name.toLowerCase().includes(term);
    });

    const newContacts = matchedUsers.filter(u => !existingChatUserIds.has(u.uid));

    return { chats: filteredChats, users: newContacts };
  }, [search, allUsers, chats]);

  const handleStartNewChat = (user: User) => {
    // Check if chat already exists
    const existingChat = chats.find(c => c.participants.includes(user.uid));

    if (existingChat) {
      onChatSelect(existingChat);
    } else {
      // Create a temporary mock chat
      const newChat: Chat = {
        id: 'new_' + user.uid,
        participants: ['current', user.uid],
        updatedAt: Date.now(),
        lastMessage: undefined
      };
      setChats(prev => [newChat, ...prev]);
      onChatSelect(newChat);
    }
    setSearch('');
  };

  const formatTime = (ts: number) => {
    const now = Date.now();
    const diff = now - ts;
    if (diff < 24 * 60 * 60 * 1000) {
      return new Date(ts).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
    }
    return new Date(ts).toLocaleDateString([], { month: 'short', day: 'numeric' });
  };

  const getChatUser = (chat: Chat) => {
    const otherId = chat.participants.find(p => p !== 'current') || '';
    return allUsers.find(u => u.uid === otherId) || {
      uid: otherId,
      name: 'User ' + otherId.slice(0, 4),
      photoURL: `https://picsum.photos/seed/${otherId}/200`,
      status: 'offline'
    } as User;
  };

  return (
    <div className="w-full h-full flex flex-col bg-white dark:bg-slate-900 z-10 transition-colors">
      {/* Header */}
      <div className="p-4 flex items-center justify-between border-b border-slate-100 dark:border-slate-800">
        <div className="flex items-center gap-3 cursor-pointer group" onClick={onProfileClick}>
          <div className="relative">
            <img 
              src={currentUser.photoURL} 
              alt={currentUser.name} 
              className="w-10 h-10 rounded-full object-cover border-2 border-transparent group-hover:border-indigo-500 transition-all"
            />
            <div className="absolute bottom-0 right-0 w-3 h-3 bg-green-500 rounded-full border-2 border-white dark:border-slate-900"></div>
          </div>
          <div className="min-w-0">
            <h3 className="font-bold text-sm leading-none truncate max-w-[120px]">{currentUser.name}</h3>
            <span className="text-[10px] text-slate-500 uppercase font-bold tracking-wider">Online</span>
          </div>
        </div>
      </div>

      <StoryBar 
        currentUser={currentUser} 
        onUploadClick={onStoryUpload} 
        onStoryClick={onStoryView} 
      />

      <div className="p-4">
        <div className="relative">
          <span className="absolute inset-y-0 left-3 flex items-center text-slate-400">
            <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" /></svg>
          </span>
          <input 
            type="text" 
            placeholder="Search name or email..."
            value={search}
            onChange={(e) => setSearch(e.target.value)}
            className="w-full bg-slate-100 dark:bg-slate-800 border-none rounded-xl py-2.5 pl-10 pr-4 text-sm focus:ring-2 focus:ring-indigo-500 transition-all outline-none"
          />
        </div>
      </div>

      <div className="flex-1 overflow-y-auto space-y-1 px-2">
        {/* Existing Chats Section */}
        {searchResults.chats.length > 0 && (
          <div className="pb-2">
            {search && <h5 className="px-3 py-2 text-[10px] font-bold uppercase tracking-widest text-slate-400">Recent Chats</h5>}
            {searchResults.chats.map(chat => {
              const user = getChatUser(chat);
              const isActive = activeChatId === chat.id;

              return (
                <div 
                  key={chat.id}
                  className={`flex items-center gap-3 p-3 rounded-xl cursor-pointer transition-all active:scale-[0.98] ${isActive ? 'bg-indigo-500 text-white shadow-lg shadow-indigo-500/20' : 'hover:bg-slate-100 dark:hover:bg-slate-800'}`}
                >
                  <div className="relative flex-shrink-0" onClick={(e) => { e.stopPropagation(); onUserClick(user); }}>
                    <img src={user.photoURL} alt={user.name} className="w-12 h-12 rounded-full object-cover hover:brightness-75 transition-all" />
                    {user.status === 'online' && (
                      <div className="absolute bottom-0 right-0 w-3 h-3 bg-green-500 rounded-full border-2 border-white dark:border-slate-900"></div>
                    )}
                  </div>
                  <div className="flex-1 min-w-0" onClick={() => onChatSelect(chat)}>
                    <div className="flex justify-between items-baseline">
                      <h4 className={`font-semibold text-sm truncate ${isActive ? 'text-white' : 'text-slate-900 dark:text-slate-100'}`}>{user.name}</h4>
                      <span className={`text-[10px] font-medium ${isActive ? 'text-indigo-100' : 'text-slate-500'}`}>
                        {chat.lastMessage ? formatTime(chat.lastMessage.timestamp) : ''}
                      </span>
                    </div>
                    <p className={`text-xs truncate mt-0.5 ${isActive ? 'text-indigo-100' : 'text-slate-500 dark:text-slate-400'}`}>
                      {chat.lastMessage?.text || 'No messages yet'}
                    </p>
                  </div>
                </div>
              );
            })}
          </div>
        )}

        {/* Global User Search Results (People you haven't talked to) */}
        {searchResults.users.length > 0 && (
          <div className="pt-2">
            <h5 className="px-3 py-2 text-[10px] font-bold uppercase tracking-widest text-indigo-500">Discover New People</h5>
            {searchResults.users.map(user => (
              <div 
                key={user.uid}
                onClick={() => handleStartNewChat(user)}
                className="flex items-center gap-3 p-3 rounded-xl cursor-pointer hover:bg-indigo-50 dark:hover:bg-indigo-900/10 transition-all group"
              >
                <img src={user.photoURL} alt={user.name} className="w-10 h-10 rounded-full object-cover border border-slate-200 dark:border-slate-700" />
                <div className="flex-1 min-w-0">
                  <h4 className="font-semibold text-sm truncate text-slate-900 dark:text-slate-100">{user.name}</h4>
                  <p className="text-[10px] text-slate-500 truncate">{user.email}</p>
                </div>
                <div className="opacity-0 group-hover:opacity-100 transition-opacity">
                  <svg className="w-5 h-5 text-indigo-500" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 4v16m8-8H4" /></svg>
                </div>
              </div>
            ))}
          </div>
        )}

        {search && searchResults.chats.length === 0 && searchResults.users.length === 0 && (
          <div className="p-8 text-center">
            <p className="text-sm text-slate-500">No users found for "{search}"</p>
          </div>
        )}
      </div>

      <div className="p-4 border-t border-slate-100 dark:border-slate-800">
        <button 
          onClick={() => {
            // Simply focuses the search and clears it to show all users if needed
            setSearch('');
            const input = document.querySelector('input[placeholder="Search name or email..."]') as HTMLInputElement;
            input?.focus();
            alert("Use the search bar above to find anyone on GeminiChat!");
          }}
          className="w-full py-3 bg-indigo-500 hover:bg-indigo-600 text-white rounded-xl text-sm font-bold shadow-lg shadow-indigo-500/20 active:scale-95 transition-all flex items-center justify-center gap-2"
        >
          <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 4v16m8-8H4" /></svg>
          New Chat
        </button>
      </div>
    </div>
  );
};

