  const collection = getLocal(`db_${docRef.coll}`);
  const idx = collection.findIndex((item: any) => item.uid === docRef.id || item.id === docRef.id);
  if (idx !== -1) collection[idx] = options?.merge ? { ...collection[idx], ...data } : data;
  else collection.push({ ...data, id: docRef.id });
  saveLocal(`db_${docRef.coll}`, collection.slice(-100));
};

