import React, { useState, useEffect, useRef } from 'react';
import { User, Chat, Message } from '../../types';
import { MessageBubble } from './MessageBubble';
import { getAIResponse } from '../../gemini';
import { getUserById } from '../../firebase';

interface ChatWindowProps {
  chat: Chat;
  currentUser: User;
  onClose: () => void;
  onUserClick: (user: User) => void;
}

export const ChatWindow: React.FC<ChatWindowProps> = ({ chat, currentUser, onClose, onUserClick }) => {
  const [messages, setMessages] = useState<Message[]>([]);
  const [otherUser, setOtherUser] = useState<User | null>(null);
  const [inputText, setInputText] = useState('');
  const [isTyping, setIsTyping] = useState(false);
  const [replyingTo, setReplyingTo] = useState<Message | null>(null);
  const scrollRef = useRef<HTMLDivElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const otherId = chat.participants.find(p => p !== 'current' && p !== currentUser.uid) || '';

  // Fetch real user data from our "database"
  useEffect(() => {
    const fetchUser = async () => {
      const userData = await getUserById(otherId);
      if (userData) {
        setOtherUser(userData);
      }
    };
    fetchUser();
    // Poll for status updates (like WhatsApp)
    const interval = setInterval(fetchUser, 10000);
    return () => clearInterval(interval);
  }, [otherId]);

  useEffect(() => {
    scrollToBottom();
  }, [messages, isTyping]);

  const scrollToBottom = () => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  };

  const handleSend = async (e?: React.FormEvent) => {
    e?.preventDefault();
    const text = inputText.trim();
    if (!text) return;

    const newMessage: Message = {
      id: 'm_' + Math.random().toString(36).substr(2, 9),
      senderId: currentUser.uid,
      text: text,
      type: 'text',
      timestamp: Date.now(),
      status: 'sent',
      replyContext: replyingTo ? {
        messageId: replyingTo.id,
        text: replyingTo.text,
        senderName: replyingTo.senderId === currentUser.uid ? 'You' : (otherUser?.name || 'User')
      } : undefined
    };

    setMessages(prev => [...prev, newMessage]);
    setInputText('');
    setReplyingTo(null);

    // AI logic still works with /ai command
    if (text.toLowerCase().startsWith('/ai')) {
      setIsTyping(true);
      const prompt = text.replace('/ai', '').trim();
      const aiReply = await getAIResponse(prompt || "Tell me a joke");
      setIsTyping(false);

      const aiMessage: Message = {
        id: 'ai_' + Date.now(),
        senderId: 'gemini_ai',
        text: aiReply || "Thinking...",
        type: 'text',
        timestamp: Date.now(),
        status: 'seen'
      };
      setMessages(prev => [...prev, aiMessage]);
    }
    // AUTO-REPLIES REMOVED so users can chat properly between accounts
  };

  const handleForward = (msg: Message) => {
    const forwardedMsg: Message = {
      id: 'fwd_' + Date.now(),
      senderId: currentUser.uid,
      text: msg.text,
      type: msg.type,
      timestamp: Date.now(),
      status: 'sent',
      isForwarded: true
    };
    setMessages(prev => [...prev, forwardedMsg]);
    alert(`Forwarded to ${otherUser?.name || 'contact'}`);
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    const newMessage: Message = {
      id: 'f_' + Date.now(),
      senderId: currentUser.uid,
      text: `Sent a file: ${file.name}`,
      type: file.type.startsWith('image/') ? 'image' : 'file',
      timestamp: Date.now(),
      status: 'sent',
      fileName: file.name,
      fileUrl: URL.createObjectURL(file)
    };
    setMessages(prev => [...prev, newMessage]);
  };

  const formatLastSeen = (ts: number) => {
    const date = new Date(ts);
    const now = new Date();
    const isToday = date.toDateString() === now.toDateString();
    const time = date.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
    if (isToday) return `last seen today at ${time}`;
    return `last seen on ${date.toLocaleDateString([], { month: 'short', day: 'numeric' })} at ${time}`;
  };

  if (!otherUser) return null;

  return (
    <div className="flex-1 flex flex-col h-full bg-slate-50 dark:bg-slate-900/40 relative animate-in fade-in slide-in-from-right-4 duration-300">
      <div className="p-3 md:p-4 flex items-center justify-between glass z-10 border-b border-slate-200 dark:border-slate-800">
        <div className="flex items-center gap-2 md:gap-3">
          <button onClick={onClose} className="lg:hidden p-2 rounded-full hover:bg-slate-200 dark:hover:bg-slate-800 transition-colors">
            <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M15 19l-7-7 7-7" /></svg>
          </button>
          <div className="relative cursor-pointer group" onClick={() => onUserClick(otherUser)}>
            <img src={otherUser.photoURL} alt={otherUser.name} className="w-9 h-9 md:w-10 md:h-10 rounded-full object-cover group-hover:brightness-90 transition-all" />
            {otherUser.status === 'online' && (
              <div className="absolute bottom-0 right-0 w-2.5 h-2.5 bg-green-500 rounded-full border-2 border-white dark:border-slate-900"></div>
            )}
          </div>
          <div className="min-w-0 cursor-pointer" onClick={() => onUserClick(otherUser)}>
            <h3 className="font-bold text-sm leading-none truncate">{otherUser.name}</h3>
            {otherUser.status === 'online' ? (
              <span className="text-[10px] text-green-500 font-bold uppercase tracking-wider">Online</span>
            ) : (
              <span className="text-[10px] text-slate-500 dark:text-slate-400">
                {formatLastSeen(otherUser.lastSeen)}
              </span>
            )}
          </div>
        </div>
      </div>

      <div ref={scrollRef} className="flex-1 overflow-y-auto p-4 space-y-4 scroll-smooth">
        {messages.length === 0 && (
          <div className="flex flex-col items-center justify-center h-full opacity-30 text-center space-y-2">
            <svg className="w-12 h-12" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="1.5" d="M8 12h.01M12 12h.01M16 12h.01M21 12c0 4.418-4.03 8-9 8a9.863 9.863 0 01-4.255-.949L3 20l1.395-3.72C3.512 15.042 3 13.574 3 12c0-4.418 4.03-8 9-8s9 3.582 9 8z" /></svg>
            <p className="text-sm">End-to-end encrypted</p>
          </div>
        )}
        {messages.map(msg => (
          <div key={msg.id} className="animate-in fade-in slide-in-from-bottom-2 duration-300">
             <MessageBubble 
              message={msg} 
              isOwn={msg.senderId === currentUser.uid} 
              isAI={msg.senderId === 'gemini_ai'} 
              onReply={setReplyingTo}
              onForward={handleForward}
            />
          </div>
        ))}
        {isTyping && (
          <div className="flex items-end gap-2 max-w-[80%]">
            <div className="bg-white dark:bg-slate-800 rounded-2xl rounded-bl-none p-3 shadow-sm border border-slate-100 dark:border-slate-700">
              <div className="flex gap-1">
                <div className="w-1.5 h-1.5 bg-indigo-400 rounded-full animate-bounce"></div>
                <div className="w-1.5 h-1.5 bg-indigo-400 rounded-full animate-bounce [animation-delay:-0.15s]"></div>
                <div className="w-1.5 h-1.5 bg-indigo-400 rounded-full animate-bounce [animation-delay:-0.3s]"></div>
              </div>
            </div>
          </div>
        )}
      </div>

      <div className="glass border-t border-slate-200 dark:border-slate-800 flex flex-col">
        {replyingTo && (
          <div className="px-4 py-2 bg-slate-100 dark:bg-slate-800/80 flex items-center justify-between border-b border-slate-200 dark:border-slate-700 animate-in slide-in-from-bottom-2">
            <div className="flex-1 min-w-0 border-l-4 border-indigo-500 pl-3">
              <div className="text-[10px] font-bold text-indigo-500 uppercase">Replying to {replyingTo.senderId === currentUser.uid ? 'yourself' : otherUser.name}</div>
              <p className="text-xs text-slate-500 truncate italic">{replyingTo.text}</p>
            </div>
            <button onClick={() => setReplyingTo(null)} className="p-1.5 hover:bg-slate-200 dark:hover:bg-slate-700 rounded-full">
              <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M6 18L18 6M6 6l12 12" /></svg>
            </button>
          </div>
        )}

        <form onSubmit={handleSend} className="p-3 md:p-4 flex items-end gap-2 md:gap-3 max-w-5xl mx-auto w-full">
          <div className="flex items-center gap-1 pb-1">
            <button type="button" onClick={() => fileInputRef.current?.click()} className="p-2 rounded-full hover:bg-indigo-50 dark:hover:bg-slate-800 text-indigo-500 transition-all">
              <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M15.172 7l-6.586 6.586a2 2 0 102.828 2.828l6.414-6.586a4 4 0 00-5.656-5.656l-6.415 6.585a6 6 0 108.486 8.486L20.5 13" /></svg>
            </button>
            <input type="file" ref={fileInputRef} className="hidden" onChange={handleFileUpload} />
          </div>
          <div className="flex-1 relative">
            <textarea 
              value={inputText}
              onChange={(e) => setInputText(e.target.value)}
              onKeyDown={(e) => { if (e.key === 'Enter' && !e.shiftKey) { e.preventDefault(); handleSend(); } }}
              placeholder="Message..."
              rows={1}
              className="w-full bg-slate-100 dark:bg-slate-800 border-none rounded-2xl py-2.5 md:py-3 px-4 text-sm focus:ring-2 focus:ring-indigo-500 outline-none resize-none transition-all"
            />
          </div>
          <button type="submit" disabled={!inputText.trim()} className={`p-2.5 md:p-3 rounded-2xl shadow-lg transition-all ${inputText.trim() ? 'bg-indigo-500 text-white' : 'bg-slate-200 dark:bg-slate-700 text-slate-400'}`}>
            <svg className="w-6 h-6 transform rotate-90" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 19l9 2-9-18-9 18 9-2zm0 0v-8" /></svg>
          </button>
        </form>
      </div>
    </div>
  );
};

