    user.lastSeen = Date.now();
    saveLocal(STORAGE_KEY_USERS, users);
  }

  const { password, ...userProfile } = user;
  auth.currentUser = userProfile;
  localStorage.setItem(STORAGE_KEY_SESSION, JSON.stringify(userProfile));
  notifyListeners(userProfile);
  return { user: userProfile };
};

export const createUserWithEmailAndPassword = async (authObj: any, email: string, pass: string) => {
  const users = getLocal(STORAGE_KEY_USERS);
  if (users.find((u: any) => u.email === email)) throw new Error("auth/email-already-in-use");
  const newUser = { 
    uid: crypto.randomUUID(), 
    email, 
    password: pass, 
    status: 'online', 
    lastSeen: Date.now(),
    photoURL: `https://picsum.photos/seed/${Math.random()}/200`,
    name: email.split('@')[0]
  };
  users.push(newUser);
  saveLocal(STORAGE_KEY_USERS, users);

  const { password, ...userProfile } = newUser;
  auth.currentUser = userProfile;
  localStorage.setItem(STORAGE_KEY_SESSION, JSON.stringify(userProfile));
  notifyListeners(userProfile);
  return { user: userProfile };
};

export const signOut = async () => {
  if (auth.currentUser) {
    const users = getLocal(STORAGE_KEY_USERS);
    const idx = users.findIndex((u: any) => u.uid === auth.currentUser.uid);
    if (idx !== -1) {
      users[idx].status = 'offline';
      users[idx].lastSeen = Date.now();
      saveLocal(STORAGE_KEY_USERS, users);
    }
  }
  auth.currentUser = null;
  localStorage.removeItem(STORAGE_KEY_SESSION);
  notifyListeners(null);
};

export const updateProfile = async (user: any, updates: any) => {
  const users = getLocal(STORAGE_KEY_USERS);
  const idx = users.findIndex((u: any) => u.uid === user.uid);
  if (idx !== -1) {
    users[idx] = { ...users[idx], ...updates };
    saveLocal(STORAGE_KEY_USERS, users);
    const updatedProfile = { ...users[idx] };
    delete updatedProfile.password;
    auth.currentUser = updatedProfile;
    localStorage.setItem(STORAGE_KEY_SESSION, JSON.stringify(updatedProfile));
    notifyListeners(updatedProfile);
    return updatedProfile;
  }
  throw new Error("User not found");
};

// --- REAL-TIME CHAT REPLACEMENT LOGIC ---

export const addMessage = async (msg: any) => {
  const messages = getLocal(STORAGE_KEY_MESSAGES);
  messages.push(msg);
  saveLocal(STORAGE_KEY_MESSAGES, messages.slice(-500)); // Keep last 500 messages globally

  // Update chat metadata for sidebar
  const chats = getLocal(STORAGE_KEY_CHATS);
  const chatId = [msg.senderId, msg.recipientId].sort().join('_');
  const chatIdx = chats.findIndex((c: any) => c.id === chatId);

  const chatUpdate = {
    id: chatId,
    participants: [msg.senderId, msg.recipientId],
    lastMessage: {
      text: msg.text,
      senderId: msg.senderId,
      timestamp: msg.timestamp
    },
    updatedAt: msg.timestamp
  };

  if (chatIdx !== -1) {
    chats[chatIdx] = chatUpdate;
  } else {
    chats.push(chatUpdate);
  }
  saveLocal(STORAGE_KEY_CHATS, chats);
};

export const getMessages = async (userId1: string, userId2: string) => {
  const allMessages = getLocal(STORAGE_KEY_MESSAGES);
  return allMessages.filter((m: any) => 
    (m.senderId === userId1 && m.recipientId === userId2) ||
    (m.senderId === userId2 && m.recipientId === userId1)
  );
};

export const getMyChats = async (myUid: string) => {
  const chats = getLocal(STORAGE_KEY_CHATS);
  return chats.filter((c: any) => c.participants.includes(myUid))
              .sort((a: any, b: any) => b.updatedAt - a.updatedAt);
};

export const getAllUsers = async () => getLocal(STORAGE_KEY_USERS);
export const getUserById = async (uid: string) => getLocal(STORAGE_KEY_USERS).find((u: any) => u.uid === uid);

export const addStory = async (story: any) => {
  const stories = getLocal(STORAGE_KEY_STORIES);
  stories.push({ ...story, likes: [] });
  saveLocal(STORAGE_KEY_STORIES, stories.slice(-50));
};

export const getStories = async () => {
  const stories = getLocal(STORAGE_KEY_STORIES);
  const now = Date.now();
  return stories.filter((s: any) => (now - s.timestamp) < (24 * 60 * 60 * 1000));
};

export const likeStory = async (storyId: string, userId: string) => {
  const stories = getLocal(STORAGE_KEY_STORIES);
  const idx = stories.findIndex((s: any) => s.id === storyId);
  if (idx !== -1) {
    stories[idx].likes = stories[idx].likes || [];
    const lIdx = stories[idx].likes.indexOf(userId);
    if (lIdx === -1) stories[idx].likes.push(userId);
    else stories[idx].likes.splice(lIdx, 1);
    saveLocal(STORAGE_KEY_STORIES, stories);
  }
};

export const sendStoryReply = async (recipientId: string, senderId: string, text: string, story: any) => {
  const msg = {
    id: 'm_' + Math.random().toString(36).substr(2, 9),
    senderId,
    recipientId,
    text,
    type: 'story_reply',
    timestamp: Date.now(),
    status: 'sent',
    storyContext: {
      storyId: story.id,
      mediaUrl: story.mediaUrl,
      mediaType: story.mediaType
    }
  };
  await addMessage(msg);
  return msg;
};

export const doc = (db: any, coll: string, id: string) => ({ coll, id });
export const getDoc = async (docRef: any) => {
  const data = getLocal(`db_${docRef.coll}`).find((item: any) => item.uid === docRef.id || item.id === docRef.id);
  return { exists: () => !!data, data: () => data };
};
export const setDoc = async (docRef: any, data: any, options?: any) => {
  const collection = getLocal(`db_${docRef.coll}`);
  const idx = collection.findIndex((item: any) => item.uid === docRef.id || item.id === docRef.id);
  if (idx !== -1) collection[idx] = options?.merge ? { ...collection[idx], ...data } : data;
  else collection.push({ ...data, id: docRef.id });
  saveLocal(`db_${docRef.coll}`, collection.slice(-100));
};
export const serverTimestamp = () => Date.now();

import React, { useState, useEffect, useRef } from 'react';
import { User, Chat, Message } from '../../types';
import { MessageBubble } from './MessageBubble';
import { getAIResponse } from '../../gemini';
import { getUserById, addMessage, getMessages } from '../../firebase';

interface ChatWindowProps {
  chat: Chat;
  currentUser: User;
  onClose: () => void;
  onUserClick: (user: User) => void;
}

export const ChatWindow: React.FC<ChatWindowProps> = ({ chat, currentUser, onClose, onUserClick }) => {
  const [messages, setMessages] = useState<Message[]>([]);
  const [otherUser, setOtherUser] = useState<User | null>(null);
  const [isLoading, setIsLoading] = useState(true);
  const [inputText, setInputText] = useState('');
  const [isTyping, setIsTyping] = useState(false);
  const [replyingTo, setReplyingTo] = useState<Message | null>(null);
  const scrollRef = useRef<HTMLDivElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const otherId = chat.participants.find(p => p !== currentUser.uid) || '';

  // Polling for messages and other user status
  useEffect(() => {
    const syncChat = async () => {
      // 1. Fetch Other User Profile
      const userData = await getUserById(otherId);
      if (userData) setOtherUser(userData);

      // 2. Fetch Messages between me and them
      const chatMessages = await getMessages(currentUser.uid, otherId);
      setMessages(chatMessages);

      if (isLoading) setIsLoading(false);
    };

    syncChat();
    // Check for new messages every 2 seconds
    const interval = setInterval(syncChat, 2000);
    return () => clearInterval(interval);
  }, [otherId, currentUser.uid]);

  useEffect(() => {
    scrollToBottom();
  }, [messages, isTyping]);

  const scrollToBottom = () => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  };

  const handleSend = async (e?: React.FormEvent) => {
    e?.preventDefault();
    const text = inputText.trim();
    if (!text) return;

    const newMessage: Message = {
      id: 'm_' + Math.random().toString(36).substr(2, 9),
      senderId: currentUser.uid,
      recipientId: otherId, // Important for DB filter
      text: text,
      type: 'text',
      timestamp: Date.now(),
      status: 'sent',
      replyContext: replyingTo ? {
        messageId: replyingTo.id,
        text: replyingTo.text,
        senderName: replyingTo.senderId === currentUser.uid ? 'You' : (otherUser?.name || 'User')
      } : undefined
    };

    // Save to DB (LocalStorage)
    await addMessage(newMessage);

    // Update local state for instant feedback
    setMessages(prev => [...prev, newMessage]);
    setInputText('');
    setReplyingTo(null);

    // AI command logic
    if (text.toLowerCase().startsWith('/ai')) {
      setIsTyping(true);
      const prompt = text.replace('/ai', '').trim();
      const aiReply = await getAIResponse(prompt || "Tell me a joke");
      setIsTyping(false);

      const aiMessage: Message = {
        id: 'ai_' + Date.now(),
        senderId: 'gemini_ai',
        recipientId: currentUser.uid,
        text: aiReply || "Thinking...",
        type: 'text',
        timestamp: Date.now(),
        status: 'seen'
      };
      await addMessage(aiMessage);
    }
  };

  const handleForward = async (msg: Message) => {
    const forwardedMsg: Message = {
      id: 'fwd_' + Date.now(),
      senderId: currentUser.uid,
      recipientId: otherId,
      text: msg.text,
      type: msg.type,
      timestamp: Date.now(),
      status: 'sent',
      isForwarded: true
    };
    await addMessage(forwardedMsg);
    alert(`Forwarded to ${otherUser?.name || 'contact'}`);
  };

  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    const newMessage: Message = {
      id: 'f_' + Date.now(),
      senderId: currentUser.uid,
      recipientId: otherId,
      text: `Sent a file: ${file.name}`,
      type: file.type.startsWith('image/') ? 'image' : 'file',
      timestamp: Date.now(),
      status: 'sent',
      fileName: file.name,
      fileUrl: URL.createObjectURL(file)
    };
    await addMessage(newMessage);
  };

  const formatLastSeen = (ts: number) => {
    const date = new Date(ts);
    const now = new Date();
    const isToday = date.toDateString() === now.toDateString();
    const time = date.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
    if (isToday) return `last seen today at ${time}`;
    return `last seen on ${date.toLocaleDateString([], { month: 'short', day: 'numeric' })} at ${time}`;
  };

  if (isLoading) {
    return (
      <div className="flex-1 flex flex-col items-center justify-center h-full bg-slate-50 dark:bg-slate-900/40">
        <div className="w-10 h-10 border-4 border-indigo-500 border-t-transparent rounded-full animate-spin mb-4"></div>
        <p className="text-slate-500 text-sm font-medium animate-pulse">Loading conversation...</p>
      </div>
    );
  }

  if (!otherUser) return null;

  return (
    <div className="flex-1 flex flex-col h-full bg-slate-50 dark:bg-slate-900/40 relative animate-in fade-in slide-in-from-right-4 duration-300">
      <div className="p-3 md:p-4 flex items-center justify-between glass z-10 border-b border-slate-200 dark:border-slate-800">
        <div className="flex items-center gap-2 md:gap-3">
          <button onClick={onClose} className="lg:hidden p-2 rounded-full hover:bg-slate-200 dark:hover:bg-slate-800 transition-colors">
            <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M15 19l-7-7 7-7" /></svg>
          </button>
          <div className="relative cursor-pointer group" onClick={() => onUserClick(otherUser)}>
            <img src={otherUser.photoURL} alt={otherUser.name} className="w-9 h-9 md:w-10 md:h-10 rounded-full object-cover group-hover:brightness-90 transition-all" />
            {otherUser.status === 'online' && (
              <div className="absolute bottom-0 right-0 w-2.5 h-2.5 bg-green-500 rounded-full border-2 border-white dark:border-slate-900"></div>
            )}
          </div>
          <div className="min-w-0 cursor-pointer" onClick={() => onUserClick(otherUser)}>
            <h3 className="font-bold text-sm leading-none truncate">{otherUser.name}</h3>
            {otherUser.status === 'online' ? (
              <span className="text-[10px] text-green-500 font-bold uppercase tracking-wider">Online</span>
            ) : (
              <span className="text-[10px] text-slate-500 dark:text-slate-400">
                {formatLastSeen(otherUser.lastSeen)}
              </span>
            )}
          </div>
        </div>
      </div>

      <div ref={scrollRef} className="flex-1 overflow-y-auto p-4 space-y-4 scroll-smooth">
        {messages.length === 0 && (
          <div className="flex flex-col items-center justify-center h-full opacity-30 text-center space-y-2">
            <svg className="w-12 h-12" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="1.5" d="M8 12h.01M12 12h.01M16 12h.01M21 12c0 4.418-4.03 8-9 8a9.863 9.863 0 01-4.255-.949L3 20l1.395-3.72C3.512 15.042 3 13.574 3 12c0-4.418 4.03-8 9-8s9 3.582 9 8z" /></svg>
            <p className="text-sm">End-to-end encrypted</p>
          </div>
        )}
        {messages.map(msg => (
          <div key={msg.id} className="animate-in fade-in slide-in-from-bottom-2 duration-300">
             <MessageBubble 
              message={msg} 
              isOwn={msg.senderId === currentUser.uid} 
              isAI={msg.senderId === 'gemini_ai'} 
              onReply={setReplyingTo}
              onForward={handleForward}
            />
          </div>
        ))}
        {isTyping && (
          <div className="flex items-end gap-2 max-w-[80%]">
            <div className="bg-white dark:bg-slate-800 rounded-2xl rounded-bl-none p-3 shadow-sm border border-slate-100 dark:border-slate-700">
              <div className="flex gap-1">
                <div className="w-1.5 h-1.5 bg-indigo-400 rounded-full animate-bounce"></div>
                <div className="w-1.5 h-1.5 bg-indigo-400 rounded-full animate-bounce [animation-delay:-0.15s]"></div>
                <div className="w-1.5 h-1.5 bg-indigo-400 rounded-full animate-bounce [animation-delay:-0.3s]"></div>
              </div>
            </div>
          </div>
        )}
      </div>

      <div className="glass border-t border-slate-200 dark:border-slate-800 flex flex-col">
        {replyingTo && (
          <div className="px-4 py-2 bg-slate-100 dark:bg-slate-800/80 flex items-center justify-between border-b border-slate-200 dark:border-slate-700 animate-in slide-in-from-bottom-2">
            <div className="flex-1 min-w-0 border-l-4 border-indigo-500 pl-3">
              <div className="text-[10px] font-bold text-indigo-500 uppercase">Replying to {replyingTo.senderId === currentUser.uid ? 'yourself' : otherUser.name}</div>
              <p className="text-xs text-slate-500 truncate italic">{replyingTo.text}</p>
            </div>
            <button onClick={() => setReplyingTo(null)} className="p-1.5 hover:bg-slate-200 dark:hover:bg-slate-700 rounded-full">
              <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M6 18L18 6M6 6l12 12" /></svg>
            </button>
          </div>
        )}

        <form onSubmit={handleSend} className="p-3 md:p-4 flex items-end gap-2 md:gap-3 max-w-5xl mx-auto w-full">
          <div className="flex items-center gap-1 pb-1">
            <button type="button" onClick={() => fileInputRef.current?.click()} className="p-2 rounded-full hover:bg-indigo-50 dark:hover:bg-slate-800 text-indigo-500 transition-all">
              <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M15.172 7l-6.586 6.586a2 2 0 102.828 2.828l6.414-6.586a4 4 0 00-5.656-5.656l-6.415 6.585a6 6 0 108.486 8.486L20.5 13" /></svg>
            </button>
            <input type="file" ref={fileInputRef} className="hidden" onChange={handleFileUpload} />
          </div>
          <div className="flex-1 relative">
            <textarea 
              value={inputText}
              onChange={(e) => setInputText(e.target.value)}
              onKeyDown={(e) => { if (e.key === 'Enter' && !e.shiftKey) { e.preventDefault(); handleSend(); } }}
              placeholder="Message..."
              rows={1}
              className="w-full bg-slate-100 dark:bg-slate-800 border-none rounded-2xl py-2.5 md:py-3 px-4 text-sm focus:ring-2 focus:ring-indigo-500 outline-none resize-none transition-all"
            />
          </div>
          <button type="submit" disabled={!inputText.trim()} className={`p-2.5 md:p-3 rounded-2xl shadow-lg transition-all ${inputText.trim() ? 'bg-indigo-500 text-white' : 'bg-slate-200 dark:bg-slate-700 text-slate-400'}`}>
            <svg className="w-6 h-6 transform rotate-90" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 19l9 2-9-18-9 18 9-2zm0 0v-8" /></svg>
          </button>
        </form>
      </div>
    </div>
  );
};

import React, { useState, useMemo, useEffect } from 'react';
import { User, Chat, Story } from '../../types';
import { StoryBar } from './StoryBar';
import { getAllUsers, getMyChats } from '../../firebase';

interface SidebarProps {
  currentUser: User;
  onChatSelect: (chat: Chat) => void;
  onProfileClick: () => void;
  activeChatId?: string;
  onStoryUpload: () => void;
  onStoryView: (stories: Story[]) => void;
  onUserClick: (user: User) => void;
}

export const Sidebar: React.FC<SidebarProps> = ({ 
  currentUser, 
  onChatSelect, 
  onProfileClick, 
  activeChatId, 
  onStoryUpload, 
  onStoryView,
  onUserClick
}) => {
  const [search, setSearch] = useState('');
  const [allUsers, setAllUsers] = useState<User[]>([]);
  const [chats, setChats] = useState<Chat[]>([]);

  // Sync Chats and Users
  useEffect(() => {
    const syncData = async () => {
      const users = await getAllUsers();
      setAllUsers(users.filter((u: User) => u.uid !== currentUser.uid));

      const myChats = await getMyChats(currentUser.uid);
      setChats(myChats);
    };

    syncData();
    const interval = setInterval(syncData, 3000); // Polling for new chats
    return () => clearInterval(interval);
  }, [currentUser.uid]);

  const searchResults = useMemo(() => {
    const term = search.toLowerCase().trim();

    const existingChatUserIds = new Set(
      chats.flatMap(c => c.participants).filter(p => p !== currentUser.uid)
    );

    if (!term) return { chats, users: [] };

    const matchedUsers = allUsers.filter(u => 
      u.name.toLowerCase().includes(term) || u.email.toLowerCase().includes(term)
    );

    const filteredChats = chats.filter(chat => {
      const otherId = chat.participants.find(p => p !== currentUser.uid) || '';
      const user = allUsers.find(u => u.uid === otherId);
      return user?.name.toLowerCase().includes(term);
    });

    const newContacts = matchedUsers.filter(u => !existingChatUserIds.has(u.uid));

    return { chats: filteredChats, users: newContacts };
  }, [search, allUsers, chats, currentUser.uid]);

  const handleStartNewChat = (user: User) => {
    const existingChat = chats.find(c => c.participants.includes(user.uid));

    if (existingChat) {
      onChatSelect(existingChat);
    } else {
      const newChat: Chat = {
        id: [currentUser.uid, user.uid].sort().join('_'),
        participants: [currentUser.uid, user.uid],
        updatedAt: Date.now(),
        lastMessage: undefined
      };
      setChats(prev => [newChat, ...prev]);
      onChatSelect(newChat);
    }
    setSearch('');
  };

  const formatTime = (ts: number) => {
    const now = Date.now();
    const diff = now - ts;
    if (diff < 24 * 60 * 60 * 1000) {
      return new Date(ts).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
    }
    return new Date(ts).toLocaleDateString([], { month: 'short', day: 'numeric' });
  };

  const getChatUser = (chat: Chat) => {
    const otherId = chat.participants.find(p => p !== currentUser.uid) || '';
    return allUsers.find(u => u.uid === otherId) || {
      uid: otherId,
      name: 'User ' + otherId.slice(0, 4),
      photoURL: `https://picsum.photos/seed/${otherId}/200`,
      status: 'offline',
      lastSeen: Date.now()
    } as User;
  };

  return (
    <div className="w-full h-full flex flex-col bg-white dark:bg-slate-900 z-10 transition-colors">
      <div className="p-4 flex items-center justify-between border-b border-slate-100 dark:border-slate-800">
        <div className="flex items-center gap-3 cursor-pointer group" onClick={onProfileClick}>
          <div className="relative">
            <img 
              src={currentUser.photoURL} 
              alt={currentUser.name} 
              className="w-10 h-10 rounded-full object-cover border-2 border-transparent group-hover:border-indigo-500 transition-all"
            />
            <div className="absolute bottom-0 right-0 w-3 h-3 bg-green-500 rounded-full border-2 border-white dark:border-slate-900"></div>
          </div>
          <div className="min-w-0">
            <h3 className="font-bold text-sm leading-none truncate max-w-[120px]">{currentUser.name}</h3>
            <span className="text-[10px] text-slate-500 uppercase font-bold tracking-wider">Online</span>
          </div>
        </div>
      </div>

      <StoryBar 
        currentUser={currentUser} 
        onUploadClick={onStoryUpload} 
        onStoryClick={onStoryView} 
      />

      <div className="p-4">
        <div className="relative">
          <span className="absolute inset-y-0 left-3 flex items-center text-slate-400">
            <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" /></svg>
          </span>
          <input 
            type="text" 
            placeholder="Search name or email..."
            value={search}
            onChange={(e) => setSearch(e.target.value)}
            className="w-full bg-slate-100 dark:bg-slate-800 border-none rounded-xl py-2.5 pl-10 pr-4 text-sm focus:ring-2 focus:ring-indigo-500 transition-all outline-none"
          />
        </div>
      </div>

      <div className="flex-1 overflow-y-auto space-y-1 px-2">
        {searchResults.chats.length > 0 && (
          <div className="pb-2">
            <h5 className="px-3 py-2 text-[10px] font-bold uppercase tracking-widest text-slate-400">Conversations</h5>
            {searchResults.chats.map(chat => {
              const user = getChatUser(chat);
              const isActive = activeChatId === chat.id;

              return (
                <div 
                  key={chat.id}
                  className={`flex items-center gap-3 p-3 rounded-xl cursor-pointer transition-all active:scale-[0.98] ${isActive ? 'bg-indigo-500 text-white shadow-lg shadow-indigo-500/20' : 'hover:bg-slate-100 dark:hover:bg-slate-800'}`}
                >
                  <div className="relative flex-shrink-0" onClick={(e) => { e.stopPropagation(); onUserClick(user); }}>
                    <img src={user.photoURL} alt={user.name} className="w-12 h-12 rounded-full object-cover hover:brightness-75 transition-all" />
                    {user.status === 'online' && (
                      <div className="absolute bottom-0 right-0 w-3 h-3 bg-green-500 rounded-full border-2 border-white dark:border-slate-900"></div>
                    )}
                  </div>
                  <div className="flex-1 min-w-0" onClick={() => onChatSelect(chat)}>
                    <div className="flex justify-between items-baseline">
                      <h4 className={`font-semibold text-sm truncate ${isActive ? 'text-white' : 'text-slate-900 dark:text-slate-100'}`}>{user.name}</h4>
                      <span className={`text-[10px] font-medium ${isActive ? 'text-indigo-100' : 'text-slate-500'}`}>
                        {chat.lastMessage ? formatTime(chat.lastMessage.timestamp) : ''}
                      </span>
                    </div>
                    <p className={`text-xs truncate mt-0.5 ${isActive ? 'text-indigo-100' : 'text-slate-500 dark:text-slate-400'}`}>
                      {chat.lastMessage?.text || 'No messages yet'}
                    </p>
                  </div>
                </div>
              );
            })}
          </div>
        )}

        {searchResults.users.length > 0 && (
          <div className="pt-2">
            <h5 className="px-3 py-2 text-[10px] font-bold uppercase tracking-widest text-indigo-500">Global Search</h5>
            {searchResults.users.map(user => (
              <div 
                key={user.uid}
                onClick={() => handleStartNewChat(user)}
                className="flex items-center gap-3 p-3 rounded-xl cursor-pointer hover:bg-indigo-50 dark:hover:bg-indigo-900/10 transition-all group"
              >
                <img src={user.photoURL} alt={user.name} className="w-10 h-10 rounded-full object-cover border border-slate-200 dark:border-slate-700" />
                <div className="flex-1 min-w-0">
                  <h4 className="font-semibold text-sm truncate text-slate-900 dark:text-slate-100">{user.name}</h4>
                  <p className="text-[10px] text-slate-500 truncate">{user.email}</p>
                </div>
                <div className="opacity-0 group-hover:opacity-100 transition-opacity">
                  <svg className="w-5 h-5 text-indigo-500" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 4v16m8-8H4" /></svg>
                </div>
              </div>
            ))}
          </div>
        )}

        {chats.length === 0 && !search && (
          <div className="p-8 text-center">
            <p className="text-sm text-slate-500">No chats yet. Search for someone to start messaging!</p>
          </div>
        )}
      </div>
    </div>
  );
};

export interface User {
  uid: string;
  name: string;
  email: string;
  photoURL: string;
  status: 'online' | 'offline';
  lastSeen: number;
  bio?: string;
}

export type MessageType = 'text' | 'image' | 'file' | 'voice' | 'story_reply';
export type MessageStatus = 'sent' | 'delivered' | 'seen';

export interface Message {
  id: string;
  senderId: string;
  // Fix: Added missing recipientId property
  recipientId: string;
  text: string;
  type: MessageType;
  timestamp: number;
  status: MessageStatus;
  fileUrl?: string;
  fileName?: string;
  isForwarded?: boolean;
  replyContext?: {
    messageId: string;
    text: string;
    senderName: string;
  };
  storyContext?: {
    storyId: string;
    mediaUrl: string;
    mediaType: 'image' | 'video';
  };
}

export interface Story {
  id: string;
  userId: string;
  userName: string;
  userPhoto: string;
  mediaUrl: string;
  mediaType: 'image' | 'video';
  caption?: string;
  timestamp: number;
  likes?: string[]; 
}

export interface Chat {
  id: string;
  participants: string[];
  lastMessage?: {
    text: string;
    senderId: string;
    timestamp: number;
  };
  updatedAt: number;
