import React, { useState, useEffect } from 'react';
import { Story, User } from '../../types';
import { likeStory, sendStoryReply } from '../../firebase';

interface StoryViewerProps {
  stories: Story[];
  currentUser: User;
  onClose: () => void;
}

const QUICK_REACTIONS = ['😂', '❤️', '🔥', '😮', '😢', '🙌'];

export const StoryViewer: React.FC<StoryViewerProps> = ({ stories, currentUser, onClose }) => {
  const [currentIndex, setCurrentIndex] = useState(0);
  const [progress, setProgress] = useState(0);
  const [replyText, setReplyText] = useState('');
  const [isLiked, setIsLiked] = useState(false);
  const [showHeartAnim, setShowHeartAnim] = useState(false);
  const [showSentAnim, setShowSentAnim] = useState(false);
  const [isPaused, setIsPaused] = useState(false);

  const story = stories[currentIndex];

  useEffect(() => {
    setIsLiked(story.likes?.includes(currentUser.uid) || false);
    setProgress(0);
    setReplyText('');

    if (isPaused) return;

    const duration = story.mediaType === 'video' ? 10000 : 5000;
    const intervalTime = 50;
    const step = (intervalTime / duration) * 100;

    const timer = setInterval(() => {
      setProgress(prev => {
        if (prev >= 100) {
          clearInterval(timer);
          handleNext();
          return 100;
        }
        return prev + step;
      });
    }, intervalTime);

    return () => clearInterval(timer);
  }, [currentIndex, isPaused, story.id]);

  const handleNext = () => {
    if (currentIndex < stories.length - 1) {
      setCurrentIndex(prev => prev + 1);
    } else {
      onClose();
    }
  };

  const handlePrev = () => {
    if (currentIndex > 0) {
      setCurrentIndex(prev => prev - 1);
    }
  };

  const handleLike = async () => {
    if (!isLiked) {
      setShowHeartAnim(true);
      setTimeout(() => setShowHeartAnim(false), 800);
    }
    setIsLiked(!isLiked);
    await likeStory(story.id, currentUser.uid);
  };

  const triggerSentAnim = () => {
    setShowSentAnim(true);
    setTimeout(() => setShowSentAnim(false), 1500);
  };

  const handleReply = async (e?: React.FormEvent, customText?: string) => {
    e?.preventDefault();
    const text = customText || replyText.trim();
    if (!text) return;

    setReplyText('');
    setIsPaused(false);

    await sendStoryReply(story.userId, currentUser.uid, text, story);
    triggerSentAnim();

    // Auto-advance after 1 second if it was a quick reaction
    if (customText) {
      setTimeout(handleNext, 1000);
    }
  };

  return (
    <div className="fixed inset-0 z-[110] bg-black flex flex-col transition-all">
      {/* Progress Bars */}
      <div className="flex gap-1.5 p-4 absolute top-0 inset-x-0 z-20">
        {stories.map((_, idx) => {
          const barWidth = idx < currentIndex ? '100%' : idx === currentIndex ? progress + '%' : '0%';
          return (
            <div key={idx} className="h-1 flex-1 bg-white/20 rounded-full overflow-hidden">
              <div 
                className="h-full bg-white transition-all duration-100 ease-linear"
                style={{ width: barWidth }}
              />
            </div>
          );
        })}
      </div>

      {/* Header */}
      <div className="absolute top-8 inset-x-0 px-4 flex items-center justify-between z-20">
        <div className="flex items-center gap-3">
          <img src={story.userPhoto} className="w-10 h-10 rounded-full border border-white/20 object-cover" alt="" />
          <div>
            <h4 className="text-white font-bold text-sm">{story.userName}</h4>
            <span className="text-white/60 text-[10px] uppercase font-bold tracking-widest">
              {new Date(story.timestamp).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
            </span>
          </div>
        </div>
        <button onClick={onClose} className="p-2 text-white/70 hover:text-white transition-colors">
          <svg className="w-8 h-8" fill="none" stroke="currentColor" viewBox="0 0 24 24">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M6 18L18 6M6 6l12 12" />
          </svg>
        </button>
      </div>

      {/* Content */}
      <div className="flex-1 flex items-center justify-center relative select-none">
        <div className="absolute inset-y-0 left-0 w-1/4 z-30 cursor-pointer" onClick={handlePrev} />
        <div className="absolute inset-y-0 right-0 w-1/4 z-30 cursor-pointer" onClick={handleNext} />

        {showHeartAnim && (
          <div className="absolute z-40 animate-ping">
            <svg className="w-32 h-32 text-red-500" fill="currentColor" viewBox="0 0 24 24">
              <path d="M12 21.35l-1.45-1.32C5.4 15.36 2 12.28 2 8.5 2 5.42 4.42 3 7.5 3c1.74 0 3.41.81 4.5 2.09C13.09 3.81 14.76 3 16.5 3 19.58 3 22 5.42 22 8.5c0 3.78-3.4 6.86-8.55 11.54L12 21.35z" />
            </svg>
          </div>
        )}

        {showSentAnim && (
          <div className="absolute z-50 bg-white/20 backdrop-blur-md px-6 py-3 rounded-full text-white font-bold animate-in fade-in zoom-in duration-300">
            Reply Sent ✨
          </div>
        )}

        {story.mediaType === 'video' ? (
          <video 
            src={story.mediaUrl} 
            className="max-h-full w-full object-contain" 
            autoPlay 
            playsInline 
            onPlay={() => setIsPaused(false)}
          />
        ) : (
          <img 
            src={story.mediaUrl} 
            className="max-h-full w-full object-contain shadow-2xl transition-transform active:scale-95" 
            alt="" 
            onDoubleClick={handleLike}
          />
        )}

        {story.caption && (
          <div className="absolute bottom-40 inset-x-0 p-8 text-center bg-gradient-to-t from-black/80 via-black/40 to-transparent z-10">
            <p className="text-white text-lg font-medium drop-shadow-lg">{story.caption}</p>
          </div>
        )}
      </div>

      {/* Footer */}
      <div className="p-4 md:p-6 glass bg-black/40 border-t border-white/10 z-50 transition-all">
        <div className="max-w-xl mx-auto flex flex-col gap-4">

          {/* Quick Reactions */}
          {!replyText && (
            <div className="flex justify-between items-center px-2 animate-in slide-in-from-bottom-2">
              {QUICK_REACTIONS.map(emoji => (
                <button 
                  key={emoji} 
                  onClick={() => handleReply(undefined, emoji)}
                  className="text-2xl hover:scale-125 transition-transform p-2 active:scale-90"
                >
                  {emoji}
                </button>
              ))}
            </div>
          )}

          <div className="flex items-center gap-4">
            <form onSubmit={handleReply} className="flex-1 flex items-center gap-3">
              <input 
                type="text"
                placeholder={`Reply to ${story.userName}...`}
                value={replyText}
                onFocus={() => setIsPaused(true)}
                onBlur={() => !replyText && setIsPaused(false)}
                onChange={(e) => setReplyText(e.target.value)}
                className="flex-1 bg-white/10 border border-white/20 rounded-full px-5 py-3 text-white placeholder-white/50 focus:outline-none focus:ring-2 focus:ring-indigo-500 transition-all text-sm"
              />
              {replyText.trim() && (
                <button type="submit" className="text-white bg-indigo-500 p-3 rounded-full hover:bg-indigo-600 transition-all active:scale-90 shadow-lg shadow-indigo-500/20">
                  <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 19l9 2-9-18-9 18 9-2zm0 0v-8" />
                  </svg>
                </button>
              )}
            </form>

            <button 
              onClick={handleLike}
              className={`p-2.5 rounded-full transition-all active:scale-125 ${isLiked ? 'text-red-500 scale-110' : 'text-white/70 hover:text-white'}`}
            >
              <svg className={`w-7 h-7 ${isLiked ? 'fill-current' : 'fill-none stroke-current'}`} strokeWidth="2" viewBox="0 0 24 24">
                <path d="M12 21.35l-1.45-1.32C5.4 15.36 2 12.28 2 8.5 2 5.42 4.42 3 7.5 3c1.74 0 3.41.81 4.5 2.09C13.09 3.81 14.76 3 16.5 3 19.58 3 22 5.42 22 8.5c0 3.78-3.4 6.86-8.55 11.54L12 21.35z" />
              </svg>
            </button>
          </div>
        </div>
      </div>
    </div>
  );
};

import React, { useState, useRef, useEffect } from 'react';
import { Message } from '../../types';

interface MessageBubbleProps {
  message: Message;
  isOwn: boolean;
  isAI?: boolean;
  onReply: (msg: Message) => void;
  onForward: (msg: Message) => void;
}

export const MessageBubble: React.FC<MessageBubbleProps> = ({ message, isOwn, isAI, onReply, onForward }) => {
  const [showMenu, setShowMenu] = useState(false);
  const menuRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (menuRef.current && !menuRef.current.contains(event.target as Node)) {
        setShowMenu(false);
      }
    };
    if (showMenu) document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, [showMenu]);

  const formatTime = (ts: number) => {
    return new Date(ts).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
  };

  const handleCopy = () => {
    navigator.clipboard.writeText(message.text);
    setShowMenu(false);
  };

  const renderStatus = () => {
    if (!isOwn) return null;
    switch (message.status) {
      case 'sent':
        return <svg className="w-3.5 h-3.5 text-slate-400" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M5 13l4 4L19 7" /></svg>;
      case 'delivered':
        return <div className="flex -space-x-2"><svg className="w-3.5 h-3.5 text-slate-400" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M5 13l4 4L19 7" /></svg><svg className="w-3.5 h-3.5 text-slate-400" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M5 13l4 4L19 7" /></svg></div>;
      case 'seen':
        return <div className="flex -space-x-2"><svg className="w-3.5 h-3.5 text-blue-400" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M5 13l4 4L19 7" /></svg><svg className="w-3.5 h-3.5 text-blue-400" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M5 13l4 4L19 7" /></svg></div>;
    }
  };

  return (
    <div className={`flex w-full ${isOwn ? 'justify-end' : 'justify-start'} mb-1`}>
      <div className={`flex flex-col max-w-[85%] md:max-w-[75%] group ${isOwn ? 'items-end' : 'items-start'} relative`}>

        {/* Interaction Menu */}
        {showMenu && (
          <div 
            ref={menuRef}
            className={`absolute z-50 bottom-full mb-2 bg-white dark:bg-slate-800 rounded-xl shadow-2xl border border-slate-100 dark:border-slate-700 p-1 flex flex-col min-w-[120px] animate-in zoom-in-95 duration-100 ${isOwn ? 'right-0' : 'left-0'}`}
          >
            <button onClick={() => { onReply(message); setShowMenu(false); }} className="flex items-center gap-2 px-3 py-2 hover:bg-slate-100 dark:hover:bg-slate-700 rounded-lg text-xs font-semibold transition-colors">
              <svg className="w-4 h-4 text-blue-500" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M3 10h10a8 8 0 018 8v2M3 10l6 6m-6-6l6-6" /></svg>
              Reply
            </button>
            <button onClick={handleCopy} className="flex items-center gap-2 px-3 py-2 hover:bg-slate-100 dark:hover:bg-slate-700 rounded-lg text-xs font-semibold transition-colors">
              <svg className="w-4 h-4 text-indigo-500" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M8 5H6a2 2 0 00-2 2v12a2 2 0 002 2h10a2 2 0 002-2v-1M8 5a2 2 0 002 2h2a2 2 0 002-2M8 5a2 2 0 012-2h2a2 2 0 012 2m0 0h2a2 2 0 012 2v3m2 4H10m0 0l3-3m-3 3l3 3" /></svg>
              Copy
            </button>
            <button onClick={() => { onForward(message); setShowMenu(false); }} className="flex items-center gap-2 px-3 py-2 hover:bg-slate-100 dark:hover:bg-slate-700 rounded-lg text-xs font-semibold transition-colors">
              <svg className="w-4 h-4 text-green-500" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M14 5l7 7m0 0l-7 7m7-7H3" /></svg>
              Forward
            </button>
          </div>
        )}

        <div 
          onClick={() => setShowMenu(!showMenu)}
          className={`relative p-3 rounded-2xl shadow-sm transition-all duration-300 cursor-pointer active:scale-95 ${
            isOwn 
            ? 'bg-indigo-600 text-white rounded-tr-none' 
            : isAI
              ? 'bg-gradient-to-br from-purple-600 to-indigo-600 text-white rounded-tl-none ring-2 ring-purple-500/20 shadow-indigo-500/10'
              : 'bg-white dark:bg-slate-800 text-slate-900 dark:text-slate-100 rounded-tl-none border border-slate-100 dark:border-slate-700/50'
          }`}
        >
          {message.isForwarded && (
            <div className="flex items-center gap-1 mb-1 opacity-60 text-[9px] italic">
              <svg className="w-3 h-3" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M14 5l7 7m0 0l-7 7m7-7H3" /></svg>
              Forwarded
            </div>
          )}

          {isAI && !message.isForwarded && (
            <div className="flex items-center gap-1.5 mb-1 opacity-80">
              <div className="w-4 h-4 bg-white/20 rounded-full flex items-center justify-center">
                <svg className="w-2.5 h-2.5 text-white" fill="currentColor" viewBox="0 0 24 24">
                  <path d="M12 2L15.09 8.26L22 9.27L17 14.14L18.18 21.02L12 17.77L5.82 21.02L7 14.14L2 9.27L8.91 8.26L12 2Z" />
                </svg>
              </div>
              <span className="text-[10px] font-bold uppercase tracking-widest">Gemini AI</span>
            </div>
          )}

          {/* Reply Context */}
          {message.replyContext && (
            <div className={`mb-2 p-2 rounded-xl text-xs border-l-4 ${isOwn ? 'bg-indigo-700/50 border-indigo-300' : 'bg-slate-100 dark:bg-slate-700 border-indigo-500'}`}>
              <div className="font-bold text-indigo-400 dark:text-indigo-300 mb-0.5">{message.replyContext.senderName}</div>
              <p className="opacity-70 line-clamp-2 italic">{message.replyContext.text}</p>
            </div>
          )}

          {/* Story Reply Section */}
          {message.type === 'story_reply' && message.storyContext && (
            <div className={`mb-2 p-2 rounded-xl flex gap-3 border ${isOwn ? 'bg-white/10 border-white/20' : 'bg-slate-50 dark:bg-slate-700/50 border-slate-200 dark:border-slate-600'}`}>
              <div className="w-10 h-14 shrink-0 bg-black/20 rounded-lg overflow-hidden relative">
                {message.storyContext.mediaType === 'video' ? (
                  <video src={message.storyContext.mediaUrl} className="w-full h-full object-cover" />
                ) : (
                  <img src={message.storyContext.mediaUrl} className="w-full h-full object-cover" alt="Story preview" />
                )}
                <div className="absolute inset-0 bg-black/10"></div>
              </div>
              <div className="flex-1 min-w-0 flex flex-col justify-center">
                <span className={`text-[10px] font-bold uppercase tracking-wider ${isOwn ? 'text-indigo-200' : 'text-indigo-500'}`}>Story Reply</span>
                <p className={`text-[11px] truncate italic ${isOwn ? 'text-white/60' : 'text-slate-500'}`}>View original story</p>
              </div>
            </div>
          )}

          {message.type === 'image' && message.fileUrl && (
            <div className="mb-2 overflow-hidden rounded-lg">
              <img src={message.fileUrl} alt="Sent file" className="w-full max-h-64 object-cover cursor-pointer hover:opacity-90 transition-opacity" />
            </div>
          )}

          <p className="text-sm leading-relaxed whitespace-pre-wrap">{message.text}</p>

          <div className={`flex items-center gap-1.5 mt-1 ${isOwn ? 'justify-end' : 'justify-start'}`}>
            <span className={`text-[9px] font-medium uppercase opacity-60`}>
              {formatTime(message.timestamp)}
            </span>
            {renderStatus()}
          </div>
        </div>
      </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { Story, User } from '../../types';
import { likeStory, sendStoryReply } from '../../firebase';

interface StoryViewerProps {
