        <button onClick={onClose} className="p-2 text-white/70 hover:text-white transition-colors bg-black/10 rounded-full backdrop-blur-sm">
          <svg className="w-8 h-8" fill="none" stroke="currentColor" viewBox="0 0 24 24">
