        <div className="max-w-xl mx-auto flex flex-col gap-4">

          {/* Quick Reactions - Only show when input is empty to save space */}
          {!replyText && (
            <div className="flex justify-between items-center px-4 animate-in slide-in-from-bottom-2 duration-200">
              {QUICK_REACTIONS.map(emoji => (
                <button 
