import React, { useState, useEffect } from 'react';
import { Story, User } from '../../types';
import { likeStory, sendStoryReply } from '../../firebase';

interface StoryViewerProps {
  stories: Story[];
  currentUser: User;
  onClose: () => void;
}

const QUICK_REACTIONS = ['😂', '❤️', '🔥', '😮', '😢', '🙌'];

export const StoryViewer: React.FC<StoryViewerProps> = ({ stories, currentUser, onClose }) => {
  const [currentIndex, setCurrentIndex] = useState(0);
  const [progress, setProgress] = useState(0);
  const [replyText, setReplyText] = useState('');
  const [isLiked, setIsLiked] = useState(false);
  const [showHeartAnim, setShowHeartAnim] = useState(false);
  const [showSentAnim, setShowSentAnim] = useState(false);
  const [isPaused, setIsPaused] = useState(false);

  const story = stories[currentIndex];

  useEffect(() => {
    setIsLiked(story.likes?.includes(currentUser.uid) || false);
    setProgress(0);

    if (isPaused) return;

    const duration = story.mediaType === 'video' ? 10000 : 5000;
    const intervalTime = 50;
    const step = (intervalTime / duration) * 100;

    const timer = setInterval(() => {
      setProgress(prev => {
        if (prev >= 100) {
          clearInterval(timer);
          handleNext();
          return 100;
        }
        return prev + step;
      });
    }, intervalTime);

    return () => clearInterval(timer);
  }, [currentIndex, isPaused, story.id]);

  const handleNext = () => {
    if (currentIndex < stories.length - 1) {
      setCurrentIndex(prev => prev + 1);
    } else {
      onClose();
    }
  };

  const handlePrev = () => {
    if (currentIndex > 0) {
      setCurrentIndex(prev => prev - 1);
    }
  };

  const handleLike = async () => {
    if (!isLiked) {
      setShowHeartAnim(true);
      setTimeout(() => setShowHeartAnim(false), 800);
    }
    setIsLiked(!isLiked);
    await likeStory(story.id, currentUser.uid);
  };

  const triggerSentAnim = () => {
    setShowSentAnim(true);
    setTimeout(() => setShowSentAnim(false), 1500);
  };

  const handleReply = async (e?: React.FormEvent, customText?: string) => {
    e?.preventDefault();
    const text = customText || replyText.trim();
    if (!text) return;

    setReplyText('');
    setIsPaused(false);

    await sendStoryReply(story.userId, currentUser.uid, text, story);
    triggerSentAnim();

    if (customText) {
      setTimeout(handleNext, 800);
    }
  };

  return (
    <div className="fixed inset-0 z-[110] bg-black flex flex-col h-[100dvh] transition-all overflow-hidden touch-none">
      {/* Top Header - Progress Bars & User Info */}
      <div className="absolute top-0 inset-x-0 z-50 pt-safe bg-gradient-to-b from-black/60 to-transparent">
        <div className="flex gap-1 p-3">
          {stories.map((_, idx) => {
            const barWidth = idx < currentIndex ? '100%' : idx === currentIndex ? progress + '%' : '0%';
            return (
              <div key={idx} className="h-1 flex-1 bg-white/20 rounded-full overflow-hidden">
                <div 
                  className="h-full bg-white transition-all duration-100 ease-linear"
                  style={{ width: barWidth }}
                />
              </div>
            );
          })}
        </div>

        <div className="px-4 pb-4 flex items-center justify-between">
          <div className="flex items-center gap-3">
            <img src={story.userPhoto} className="w-10 h-10 rounded-full border border-white/20 object-cover" alt="" />
            <div>
              <h4 className="text-white font-bold text-sm leading-none mb-1">{story.userName}</h4>
              <span className="text-white/60 text-[10px] uppercase font-bold tracking-widest">
                {new Date(story.timestamp).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
              </span>
            </div>
            {isPaused && (
              <div className="ml-2 px-2 py-0.5 bg-white/20 backdrop-blur-md rounded-md text-[9px] text-white font-bold uppercase tracking-wider animate-pulse">
                Paused
              </div>
            )}
          </div>
          <button onClick={onClose} className="p-2 text-white/70 hover:text-white transition-colors">
            <svg className="w-8 h-8" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M6 18L18 6M6 6l12 12" />
            </svg>
          </button>
        </div>
      </div>

      {/* Main Content Area - Strictly flex-1 */}
      <div className="flex-1 flex items-center justify-center relative bg-black">
        {/* Navigation Zones */}
        <div className="absolute inset-y-0 left-0 w-1/4 z-30 cursor-pointer" onClick={handlePrev} />
        <div className="absolute inset-y-0 right-0 w-1/4 z-30 cursor-pointer" onClick={handleNext} />

        {showHeartAnim && (
          <div className="absolute z-40 animate-ping">
            <svg className="w-32 h-32 text-red-500" fill="currentColor" viewBox="0 0 24 24">
              <path d="M12 21.35l-1.45-1.32C5.4 15.36 2 12.28 2 8.5 2 5.42 4.42 3 7.5 3c1.74 0 3.41.81 4.5 2.09C13.09 3.81 14.76 3 16.5 3 19.58 3 22 5.42 22 8.5c0 3.78-3.4 6.86-8.55 11.54L12 21.35z" />
            </svg>
          </div>
        )}

        {showSentAnim && (
          <div className="absolute z-50 bg-indigo-600 px-6 py-3 rounded-full text-white font-bold shadow-2xl animate-in zoom-in duration-200">
            Sent! ✨
          </div>
        )}

        <div className="w-full h-full flex items-center justify-center">
          {story.mediaType === 'video' ? (
            <video 
              src={story.mediaUrl} 
              className="max-h-full w-full object-contain" 
              autoPlay 
              playsInline 
              muted={false}
              onPlay={() => !isPaused && setIsPaused(false)}
            />
          ) : (
            <img 
              src={story.mediaUrl} 
              className="max-h-full w-full object-contain" 
              alt="" 
              onDoubleClick={handleLike}
            />
          )}
        </div>

        {story.caption && !replyText && (
          <div className="absolute bottom-8 inset-x-0 p-8 text-center bg-gradient-to-t from-black/80 to-transparent z-40">
            <p className="text-white text-lg font-medium drop-shadow-lg">{story.caption}</p>
          </div>
        )}
      </div>

      {/* Fixed Footer - Reply Box */}
      <div className="bg-black/80 backdrop-blur-xl border-t border-white/10 z-[100] safe-bottom shrink-0">
        <div className="max-w-2xl mx-auto px-4 py-3 md:py-6">
          {/* Quick Reactions - Only when input is empty */}
          {!replyText && (
            <div className="flex justify-between items-center mb-4 px-2 animate-in slide-in-from-bottom-2">
              {QUICK_REACTIONS.map(emoji => (
                <button 
                  key={emoji} 
                  onClick={() => handleReply(undefined, emoji)}
                  className="text-2xl hover:scale-125 transition-transform p-1 active:scale-90"
                >
                  {emoji}
                </button>
              ))}
            </div>
          )}

          <div className="flex items-center gap-3">
            <form onSubmit={handleReply} className="flex-1 flex items-center gap-2">
              <input 
                type="text"
                placeholder={`Reply to ${story.userName}...`}
                value={replyText}
                onFocus={() => setIsPaused(true)}
                onBlur={() => !replyText && setIsPaused(false)}
                onChange={(e) => setReplyText(e.target.value)}
                className="flex-1 bg-white/10 border border-white/20 rounded-full px-5 py-3 text-white placeholder-white/40 focus:outline-none focus:ring-2 focus:ring-indigo-500 transition-all text-sm"
              />

              {replyText.trim() ? (
                <button type="submit" className="text-white bg-indigo-500 p-3 rounded-full hover:bg-indigo-600 transition-all active:scale-90">
                  <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M12 19l9 2-9-18-9 18 9-2zm0 0v-8" />
                  </svg>
                </button>
              ) : (
                <button 
                  type="button"
                  onClick={handleLike}
                  className={`p-2 transition-all active:scale-125 ${isLiked ? 'text-red-500' : 'text-white/70 hover:text-white'}`}
                >
                  <svg className={`w-8 h-8 ${isLiked ? 'fill-current' : 'fill-none stroke-current'}`} strokeWidth="2" viewBox="0 0 24 24">
                    <path d="M12 21.35l-1.45-1.32C5.4 15.36 2 12.28 2 8.5 2 5.42 4.42 3 7.5 3c1.74 0 3.41.81 4.5 2.09C13.09 3.81 14.76 3 16.5 3 19.58 3 22 5.42 22 8.5c0 3.78-3.4 6.86-8.55 11.54L12 21.35z" />
                  </svg>
                </button>
              )}
            </form>
          </div>
        </div>
      </div>
    </div>
  );
};

