                </div>
              </div>
            ))}
          </div>
        )}

        {chats.length === 0 && !search && (
          <div className="p-8 text-center">
            <p className="text-sm text-slate-500">No chats yet. Search for someone to start messaging!</p>
          </div>
        )}
      </div>
    </div>
  );
};

