interface CreateGroupModalProps {
  currentUser: User;
  onClose: () => void;
  onCreated: (chat: any) => void;
}

export const CreateGroupModal: React.FC<CreateGroupModalProps> = ({ currentUser, onClose, onCreated }) => {
