        <div className="p-6 bg-slate-50 dark:bg-slate-800/50 rounded-b-[2.5rem]">
          <button 
            onClick={handleCreate}
            disabled={!name.trim() || selected.length === 0 || loading}
            className="w-full py-4 bg-indigo-500 text-white rounded-2xl font-bold shadow-lg shadow-indigo-500/20 active:scale-95 transition-all disabled:opacity-50"
          >
            {loading ? 'Creating...' : `Create Group (${selected.length})`}
          </button>
        </div>
      </div>
    </div>
  );
};

import React, { useState, useMemo, useEffect } from 'react';
import { User, Chat, Story } from '../../types';
import { StoryBar } from './StoryBar';
import { getAllUsers, getMyChats } from '../../firebase';
import { CreateGroupModal } from './CreateGroupModal';

interface SidebarProps {
  currentUser: User;
  onChatSelect: (chat: Chat) => void;
  onProfileClick: () => void;
  activeChatId?: string;
  onStoryUpload: () => void;
  onStoryView: (stories: Story[]) => void;
  onUserClick: (user: User) => void;
}

export const Sidebar: React.FC<SidebarProps> = ({ 
  currentUser, onChatSelect, onProfileClick, activeChatId, onStoryUpload, onStoryView, onUserClick
}) => {
  const [search, setSearch] = useState('');
  const [allUsers, setAllUsers] = useState<User[]>([]);
  const [chats, setChats] = useState<Chat[]>([]);
  const [showGroupModal, setShowGroupModal] = useState(false);

  useEffect(() => {
    const sync = async () => {
      const users = await getAllUsers();
      const myBlocked = currentUser.blockedUsers || [];
      setAllUsers(users.filter(u => u.uid !== currentUser.uid && !myBlocked.includes(u.uid)));
      const myChats = await getMyChats(currentUser.uid);
      setChats(myChats);
    };
    sync();
    const itv = setInterval(sync, 4000);
    return () => clearInterval(itv);
  }, [currentUser]);

  const isRevealingLocked = currentUser.chatLockPassword && search === currentUser.chatLockPassword;

  const searchResults = useMemo(() => {
    const term = search.toLowerCase().trim();

    // Filter out locked chats unless secret key is entered
    const visibleChats = chats.filter(c => {
      const isLocked = c.lockedBy?.includes(currentUser.uid);
      if (isRevealingLocked) return isLocked; // Show ONLY locked chats when password matches
      return !isLocked; // Normal mode: hide locked chats
    });

    if (!term || isRevealingLocked) return { chats: visibleChats, users: [] };

    const matchedUsers = allUsers.filter(u => u.name.toLowerCase().includes(term));
    const matchedChats = visibleChats.filter(c => {
      if (c.type === 'group') return c.name?.toLowerCase().includes(term);
      const otherId = c.participants.find(p => p !== currentUser.uid);
      const user = allUsers.find(u => u.uid === otherId);
      return user?.name.toLowerCase().includes(term);
    });

    return { chats: matchedChats, users: matchedUsers.filter(u => !chats.some(c => c.type === 'private' && c.participants.includes(u.uid))) };
  }, [search, allUsers, chats, currentUser.uid, isRevealingLocked]);

  const handleStartNewChat = (user: User) => {
    const existing = chats.find(c => c.type === 'private' && c.participants.includes(user.uid));
    if (existing) onChatSelect(existing);
    else onChatSelect({
      id: [currentUser.uid, user.uid].sort().join('_'),
      type: 'private', participants: [currentUser.uid, user.uid],
      updatedAt: Date.now(), lockedBy: []
    });
    setSearch('');
  };

  const getChatInfo = (chat: Chat) => {
    if (chat.type === 'group') return { name: chat.name || 'Group', photo: chat.groupIcon || `https://picsum.photos/seed/${chat.id}/200` };
    const otherId = chat.participants.find(p => p !== currentUser.uid);
    const user = allUsers.find(u => u.uid === otherId);
    return { name: user?.name || 'Contact', photo: user?.photoURL || `https://picsum.photos/seed/${otherId}/200`, status: user?.status };
  };

  return (
    <div className="w-full h-full flex flex-col bg-white dark:bg-slate-900 z-10">
      <div className="p-4 flex items-center justify-between border-b border-slate-100 dark:border-slate-800">
        <div className="flex items-center gap-3 cursor-pointer group" onClick={onProfileClick}>
          <img src={currentUser.photoURL} className="w-10 h-10 rounded-full object-cover border-2 border-transparent group-hover:border-indigo-500 transition-all" alt="" />
          <div className="min-w-0">
            <h3 className="font-bold text-sm truncate">{currentUser.name}</h3>
            <span className="text-[10px] text-slate-500 uppercase font-bold tracking-wider">Settings</span>
          </div>
        </div>
        <button onClick={() => setShowGroupModal(true)} className="p-2 text-indigo-500 hover:bg-indigo-50 dark:hover:bg-indigo-900/20 rounded-full transition-all" title="New Group">
          <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 4v16m8-8H4" /></svg>
        </button>
      </div>

      <StoryBar currentUser={currentUser} onUploadClick={onStoryUpload} onStoryClick={onStoryView} />

      <div className="p-4">
        <div className="relative">
