};

import React, { useState, useEffect, useRef } from 'react';
import { User, Chat, Message } from '../../types';
import { MessageBubble } from './MessageBubble';
import { getAIResponse } from '../../gemini';
import { getUserById, addMessage, getMessages, toggleChatLock } from '../../firebase';

interface ChatWindowProps {
  chat: Chat;
  currentUser: User;
  onClose: () => void;
  onUserClick: (user: User) => void;
}

export const ChatWindow: React.FC<ChatWindowProps> = ({ chat, currentUser, onClose, onUserClick }) => {
  const [messages, setMessages] = useState<Message[]>([]);
  const [otherUser, setOtherUser] = useState<User | null>(null);
  const [isLocked, setIsLocked] = useState(chat.lockedBy?.includes(currentUser.uid) || false);
  const [inputText, setInputText] = useState('');
  const [isTyping, setIsTyping] = useState(false);
  const scrollRef = useRef<HTMLDivElement>(null);

  const isGroup = chat.type === 'group';
  const otherId = !isGroup ? chat.participants.find(p => p !== currentUser.uid) || '' : chat.id;

  useEffect(() => {
    const sync = async () => {
      if (!isGroup) {
        const u = await getUserById(otherId);
        if (u) setOtherUser(u);
      }
      const msgs = await getMessages(isGroup ? chat.id : otherId);
      setMessages(msgs);
    };
    sync();
    const itv = setInterval(sync, 2000);
    return () => clearInterval(itv);
  }, [chat.id, otherId, isGroup]);

  useEffect(() => {
    if (scrollRef.current) scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
  }, [messages, isTyping]);

  const handleSend = async (e?: React.FormEvent) => {
    e?.preventDefault();
    const text = inputText.trim();
    if (!text) return;

    const msg: Message = {
      id: 'm_' + Math.random().toString(36).substr(2, 9),
      senderId: currentUser.uid,
      recipientId: isGroup ? chat.id : otherId,
      text, type: 'text', timestamp: Date.now(), status: 'sent'
    };

    await addMessage(msg);
    setMessages(prev => [...prev, msg]);
    setInputText('');

    if (text.toLowerCase().startsWith('/ai')) {
      setIsTyping(true);
      const res = await getAIResponse(text.replace('/ai', '').trim());
      setIsTyping(false);
      const aiMsg: Message = {
        id: 'ai_' + Date.now(),
        senderId: 'gemini_ai',
        recipientId: isGroup ? chat.id : currentUser.uid,
        text: res || "Thinking...", type: 'text', timestamp: Date.now(), status: 'seen'
      };
      await addMessage(aiMsg);
    }
  };

  const handleToggleLock = async () => {
    if (!currentUser.chatLockPassword) {
      alert("Please set a Chat Lock Password in Settings first!");
      return;
    }
    await toggleChatLock(chat.id, currentUser.uid);
    setIsLocked(!isLocked);
  };

  return (
    <div className="flex-1 flex flex-col h-full bg-slate-50 dark:bg-slate-900/40 animate-in fade-in duration-300">
      <div className="p-3 md:p-4 flex items-center justify-between glass z-10 border-b border-slate-200 dark:border-slate-800">
        <div className="flex items-center gap-3">
          <button onClick={onClose} className="lg:hidden p-2 rounded-full hover:bg-slate-200 dark:hover:bg-slate-800"><svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M15 19l-7-7 7-7" /></svg></button>
          <div className="relative cursor-pointer" onClick={() => !isGroup && otherUser && onUserClick(otherUser)}>
            <img src={isGroup ? (chat.groupIcon || `https://picsum.photos/seed/${chat.id}/200`) : otherUser?.photoURL} className="w-10 h-10 rounded-full object-cover" alt="" />
          </div>
          <div>
            <h3 className="font-bold text-sm leading-none flex items-center gap-2">
              {isGroup ? chat.name : otherUser?.name}
              {isLocked && <svg className="w-3.5 h-3.5 text-indigo-500" fill="currentColor" viewBox="0 0 24 24"><path d="M12 17c1.1 0 2-.9 2-2s-.9-2-2-2-2 .9-2 2 .9 2 2 2zm6-9h-1V6c0-2.76-2.24-5-5-5S7 3.24 7 6v2H6c-1.1 0-2 .9-2 2v10c0 1.1.9 2 2 2h12c1.1 0 2-.9 2-2V10c0-1.1-.9-2-2-2zm-6-5c1.66 0 3 1.34 3 3v2H9V6c0-1.66 1.34-3 3-3z"/></svg>}
            </h3>
            <span className="text-[10px] text-slate-500">
              {isGroup ? `${chat.participants.length} members` : (otherUser?.status === 'online' ? 'Online' : 'Last seen recently')}
            </span>
          </div>
        </div>
        <button 
          onClick={handleToggleLock}
          className={`p-2 rounded-full transition-all ${isLocked ? 'bg-indigo-500 text-white' : 'hover:bg-slate-200 dark:hover:bg-slate-800 text-slate-400'}`}
          title={isLocked ? "Unlock Chat" : "Lock Chat"}
        >
          <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 15v2m-6 4h12a2 2 0 002-2v-6a2 2 0 00-2-2H6a2 2 0 00-2 2v6a2 2 0 002 2zm10-10V7a4 4 0 00-8 0v4h8z" /></svg>
        </button>
      </div>

      <div ref={scrollRef} className="flex-1 overflow-y-auto p-4 space-y-4">
        {messages.map(msg => (
          <MessageBubble 
            key={msg.id} message={msg} isOwn={msg.senderId === currentUser.uid} 
            isAI={msg.senderId === 'gemini_ai'} onReply={()=>{}} onForward={()=>{}} 
          />
        ))}
        {isTyping && <div className="text-xs text-slate-400 animate-pulse ml-2">Gemini is thinking...</div>}
      </div>

      <form onSubmit={handleSend} className="p-4 glass border-t border-slate-200 dark:border-slate-800 flex gap-3">
        <input 
          type="text" value={inputText} onChange={e => setInputText(e.target.value)}
          placeholder="Message..." className="flex-1 bg-slate-100 dark:bg-slate-800 rounded-2xl px-5 py-3 outline-none focus:ring-2 focus:ring-indigo-500"
        />
        <button type="submit" className="p-3 bg-indigo-500 text-white rounded-2xl"><svg className="w-6 h-6 rotate-90" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 19l9 2-9-18-9 18 9-2zm0 0v-8" /></svg></button>
      </form>
    </div>
  );
};

