import { useState, useEffect } from 'react';
import { 
  auth, 
  db, 
  signInWithEmailAndPassword, 
  createUserWithEmailAndPassword, 
  signInWithPopup, 
  signOut, 
  updateProfile,
  doc,
  setDoc,
  getDoc,
  serverTimestamp
} from '../firebase';
import { User } from '../types';

export const useAuth = () => {
  const [user, setUser] = useState<User | null>(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    // Listen to mock auth state changes
    const unsubscribe = auth.onAuthStateChanged((mockUser: any) => {
      if (mockUser) {
        // Handle internal async fetch without making the outer function async
        getDoc(doc(db, 'users', mockUser.uid)).then((userDoc) => {
          const userData = userDoc.data();
          const finalUser: User = {
            uid: mockUser.uid,
            name: mockUser.displayName || userData?.name || mockUser.name || 'Anonymous',
            email: mockUser.email || userData?.email || '',
            photoURL: mockUser.photoURL || userData?.photoURL || `https://picsum.photos/seed/${mockUser.uid}/200`,
            status: 'online',
            lastSeen: Date.now(),
            ...userData
          };
          setUser(finalUser);
          setLoading(false);
        }).catch(() => {
          // Fallback if firestore doc doesn't exist yet
          setUser({
            uid: mockUser.uid,
            name: mockUser.name || mockUser.displayName || 'User',
            email: mockUser.email || '',
            photoURL: mockUser.photoURL || `https://picsum.photos/seed/${mockUser.uid}/200`,
            status: 'online',
            lastSeen: Date.now()
          });
          setLoading(false);
        });
      } else {
        setUser(null);
        setLoading(false);
      }
    });

    return () => unsubscribe();
  }, []);

  const syncUserToFirestore = async (u: any) => {
    const userRef = doc(db, 'users', u.uid);
    await setDoc(userRef, {
      uid: u.uid,
      name: u.displayName || u.name,
      email: u.email,
      photoURL: u.photoURL,
      lastSeen: serverTimestamp(),
      status: 'online'
    }, { merge: true });
  };

  const signup = async (email: string, pass: string, name: string) => {
    const res = await createUserWithEmailAndPassword(auth, email, pass);
    await updateProfile(res.user, { 
      displayName: name,
      name: name,
      photoURL: `https://picsum.photos/seed/${res.user.uid}/200`
    });

    const updatedUser = { ...res.user, name, displayName: name };
    await syncUserToFirestore(updatedUser);
    return updatedUser;
  };

  const login = async (email: string, pass: string) => {
    const res = await signInWithEmailAndPassword(auth, email, pass);
    await syncUserToFirestore(res.user);
    return res.user;
  };

  const googleSignIn = async () => {
    const res = await signInWithPopup();
    await syncUserToFirestore(res.user);
    return res.user;
  };

  const logout = async () => {
    if (user) {
      await setDoc(doc(db, 'users', user.uid), { 
        status: 'offline', 
        lastSeen: serverTimestamp() 
      }, { merge: true });
    }
    await signOut();
  };

  return { user, loading, signup, login, googleSignIn, logout };
};

import React, { useState, useEffect } from 'react';
import { useAuth } from '../../hooks/useAuth';

export const AuthView: React.FC = () => {
  const [isLogin, setIsLogin] = useState(true);
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [name, setName] = useState('');
  const [error, setError] = useState<string | null>(null);
  const [isLoading, setIsLoading] = useState(false);

  const { login, signup, googleSignIn } = useAuth();

  // Clear error when user starts typing again or switches modes
  useEffect(() => {
    if (error) setError(null);
  }, [email, password, name, isLogin]);

  const getFriendlyErrorMessage = (errCode: string) => {
    switch (errCode) {
      case 'auth/email-already-in-use':
        return "This email is already registered. Switching to Sign In...";
      case 'auth/user-not-found':
        return "No account found with this email. Please sign up or use Demo account.";
      case 'auth/wrong-password':
      case 'auth/incorrect-password':
        return "Incorrect password. Please try again.";
      case 'auth/invalid-email':
        return "Please enter a valid email address.";
      case 'auth/weak-password':
        return "Password should be at least 6 characters.";
      default:
        if (errCode.includes('user-not-found')) return "No account found with this email. Please sign up.";
        if (errCode.includes('email-already-in-use')) return "This email is already registered. Switching to Sign In...";
        return errCode.replace('Firebase: ', '').replace('auth/', '').split('-').join(' ');
    }
  };

  const handleDemoLogin = async () => {
    setIsLoading(true);
    setError(null);
    try {
      console.log("Attempting Demo Login...");
      await login('demo@example.com', 'password123');
      console.log("Demo Login successful!");
    } catch (err: any) {
      console.error("Demo Login Failed:", err);
      setError("Demo account is currently unavailable. Please try signing up.");
    } finally {
      setIsLoading(false);
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setError(null);
    setIsLoading(true);

    try {
      if (isLogin) {
        await login(email, password);
      } else {
        if (name.trim().length < 2) throw new Error("Please enter a valid name.");

        try {
          await signup(email, password, name);
        } catch (err: any) {
          if (err.message === 'auth/email-already-in-use' || err.message.includes('email-already-in-use')) {
            setIsLogin(true);
            await login(email, password);
          } else {
            throw err;
          }
        }
      }
    } catch (err: any) {
      console.error("Auth Submission Error:", err);
      const message = getFriendlyErrorMessage(err.message);
      setError(message.charAt(0).toUpperCase() + message.slice(1));
    } finally {
      setIsLoading(false);
    }
  };

  const handleGoogleSignIn = async () => {
    setError(null);
    setIsLoading(true);
    try {
      await googleSignIn();
    } catch (err: any) {
      console.error("Google Sign In Error:", err);
      setError(getFriendlyErrorMessage(err.message));
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className="h-screen w-full flex items-center justify-center bg-gradient-to-br from-indigo-600 via-purple-600 to-pink-500 p-4">
      <div className="glass w-full max-w-md p-8 rounded-3xl shadow-2xl transition-all duration-500 hover:shadow-indigo-500/20">
        <div className="text-center mb-8">
          <div className="w-16 h-16 bg-white/20 rounded-2xl flex items-center justify-center mx-auto mb-4 border border-white/30">
            <svg className="w-10 h-10 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M8 10h.01M12 10h.01M16 10h.01M9 16H5a2 2 0 01-2-2V6a2 2 0 012-2h14a2 2 0 012 2v8a2 2 0 01-2 2h-5l-5 5v-5z" />
            </svg>
          </div>
          <h1 className="text-3xl font-bold text-white mb-2 tracking-tight">GeminiChat</h1>
          <p className="text-white/70">Secure, Real-time messaging</p>
        </div>

        {error && (
          <div className="mb-6 p-3 bg-red-500/20 border border-red-500/50 rounded-xl text-red-100 text-sm flex items-center gap-2 animate-in slide-in-from-top-2">
            <svg className="w-5 h-5 shrink-0" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 8v4m0 4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z" />
            </svg>
            <span className="flex-1">{error}</span>
          </div>
        )}

        <form id="auth-form" onSubmit={handleSubmit} className="space-y-4">
          {!isLogin && (
            <div className="animate-in fade-in slide-in-from-top-2 duration-300">
              <label className="block text-white/80 text-sm font-medium mb-1 ml-1">Full Name</label>
              <input 
                type="text" 
                required
                value={name}
                onChange={(e) => setName(e.target.value)}
                placeholder="John Doe"
                disabled={isLoading}
                className="w-full bg-white/10 border border-white/20 rounded-xl px-4 py-3 text-white placeholder-white/40 focus:outline-none focus:ring-2 focus:ring-white/30 transition-all disabled:opacity-50"
              />
            </div>
          )}
          <div>
            <label className="block text-white/80 text-sm font-medium mb-1 ml-1">Email Address</label>
            <input 
              type="email" 
              required
              value={email}
              onChange={(e) => setEmail(e.target.value)}
              placeholder="you@example.com"
              disabled={isLoading}
              className="w-full bg-white/10 border border-white/20 rounded-xl px-4 py-3 text-white placeholder-white/40 focus:outline-none focus:ring-2 focus:ring-white/30 transition-all disabled:opacity-50"
            />
          </div>
          <div>
            <label className="block text-white/80 text-sm font-medium mb-1 ml-1">Password</label>
            <input 
              type="password" 
              required
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              placeholder="••••••••"
              disabled={isLoading}
              className="w-full bg-white/10 border border-white/20 rounded-xl px-4 py-3 text-white placeholder-white/40 focus:outline-none focus:ring-2 focus:ring-white/30 transition-all disabled:opacity-50"
            />
          </div>

          <button 
            type="submit" 
            disabled={isLoading}
            className="w-full bg-white text-indigo-600 font-bold py-3 rounded-xl hover:bg-slate-100 active:scale-95 transition-all shadow-lg flex items-center justify-center gap-2 disabled:opacity-70 disabled:active:scale-100"
          >
            {isLoading ? (
              <div className="w-5 h-5 border-2 border-indigo-600 border-t-transparent rounded-full animate-spin"></div>
            ) : (
              isLogin ? 'Sign In' : 'Create Account'
            )}
          </button>
        </form>

        <div className="mt-6 flex flex-col gap-3">
          <button 
            onClick={handleDemoLogin}
            disabled={isLoading}
            className="w-full bg-indigo-500/30 border border-white/30 py-3 rounded-xl text-white text-sm font-bold hover:bg-indigo-500/50 transition-all flex items-center justify-center gap-2"
          >
            {isLoading ? 'Loading...' : '🚀 Use Demo Account'}
          </button>

          <div className="flex items-center justify-center gap-4 py-2">
            <div className="h-px bg-white/20 flex-1"></div>
            <span className="text-white/40 text-[10px] font-bold uppercase">Or</span>
            <div className="h-px bg-white/20 flex-1"></div>
          </div>

          <button 
            onClick={handleGoogleSignIn}
            disabled={isLoading}
            className="w-full bg-white/10 border border-white/20 py-3 rounded-xl text-white text-sm font-medium hover:bg-white/20 transition-all flex items-center justify-center gap-3 disabled:opacity-50 shadow-inner"
          >
            <svg className="w-5 h-5" viewBox="0 0 24 24">
              <path fill="currentColor" d="M12.545,10.239v3.821h5.445c-0.712,2.315-2.647,3.972-5.445,3.972-3.332,0-6.033-2.701-6.033-6.032s2.701-6.032,6.033-6.032c1.498,0,2.866,0.549,3.921,1.453l2.814-2.814C17.503,2.988,15.139,2,12.545,2C7.021,2,2.543,6.477,2.543,12s4.478,10,10.002,10c8.396,0,10.249-7.85,9.426-11.748L12.545,10.239z"/>
            </svg>
            Google Sign In
          </button>
        </div>

        <button 
          onClick={() => {
            setIsLogin(!isLogin);
            setError(null);
          }}
          disabled={isLoading}
          className="w-full mt-8 text-white/60 hover:text-white text-sm font-medium transition-colors"
        >
          {isLogin ? "Don't have an account? Sign Up" : "Already have an account? Sign In"}
        </button>
      </div>
    </div>
  );
};

import React, { useState, useEffect, useRef } from 'react';
import { User, Chat, Message } from '../../types';
import { MessageBubble } from './MessageBubble';
import { getAIResponse } from '../../gemini';
import { getUserById, addMessage, getMessages, toggleChatLock } from '../../firebase';

interface ChatWindowProps {
  chat: Chat;
  currentUser: User;
  onClose: () => void;
  onUserClick: (user: User) => void;
}

export const ChatWindow: React.FC<ChatWindowProps> = ({ chat, currentUser, onClose, onUserClick }) => {
  const [messages, setMessages] = useState<Message[]>([]);
  const [otherUser, setOtherUser] = useState<User | null>(null);
  const [isLocked, setIsLocked] = useState(chat.lockedBy?.includes(currentUser.uid) || false);
  const [inputText, setInputText] = useState('');
  const [isTyping, setIsTyping] = useState(false);
  const scrollRef = useRef<HTMLDivElement>(null);

  const isGroup = chat.type === 'group';
  const otherId = !isGroup ? chat.participants.find(p => p !== currentUser.uid) || '' : chat.id;

  // Initial load and sync
  useEffect(() => {
    const sync = async () => {
      // 1. Fetch other user details if it's a private chat
      if (!isGroup && !otherUser) {
        const u = await getUserById(otherId);
        if (u) setOtherUser(u);
      }

      // 2. Fetch messages using the FULL chat.id (e.g. "uid1_uid2" or "group_id")
      // This matches the composite keys used in firebase.ts
      const msgs = await getMessages(chat.id);

      // Only update state if the message count has changed to prevent UI flicker
      setMessages(prev => {
        if (prev.length !== msgs.length) return msgs;
        // Check if last message ID is different (covers status updates)
        if (prev.length > 0 && msgs.length > 0 && prev[prev.length - 1].id !== msgs[msgs.length - 1].id) {
          return msgs;
        }
        return prev;
      });
    };

    sync();
    const itv = setInterval(sync, 2000);
    return () => clearInterval(itv);
  }, [chat.id, otherId, isGroup]);

  // Scroll to bottom whenever messages or typing state changes
  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTo({
        top: scrollRef.current.scrollHeight,
        behavior: 'smooth'
      });
    }
  }, [messages, isTyping]);

  const handleSend = async (e?: React.FormEvent) => {
    e?.preventDefault();
    const text = inputText.trim();
    if (!text) return;

    const msg: Message = {
      id: 'm_' + Math.random().toString(36).substr(2, 9),
      senderId: currentUser.uid,
      recipientId: isGroup ? chat.id : otherId,
      text, 
      type: 'text', 
      timestamp: Date.now(), 
      status: 'sent'
    };

    // Optimistic UI update: show message immediately
    setMessages(prev => [...prev, msg]);
    setInputText('');

    // Save to local DB (which also updates the Sidebar/Dashboard)
    await addMessage(msg);

    // AI Trigger logic
    if (text.toLowerCase().startsWith('/ai')) {
      setIsTyping(true);
      try {
        const res = await getAIResponse(text.replace('/ai', '').trim());
        const aiMsg: Message = {
          id: 'ai_' + Date.now(),
          senderId: 'gemini_ai',
          recipientId: isGroup ? chat.id : currentUser.uid,
          text: res || "I'm thinking...", 
          type: 'text', 
          timestamp: Date.now(), 
          status: 'seen'
        };
        await addMessage(aiMsg);
        // Polling will pick up the AI message, but we add it locally for speed
        setMessages(prev => [...prev, aiMsg]);
      } catch (err) {
        console.error("AI Error:", err);
      } finally {
        setIsTyping(false);
      }
    }
  };

  const handleToggleLock = async () => {
    if (!currentUser.chatLockPassword) {
      alert("Please set a Chat Lock Password in Settings first!");
      return;
    }
    await toggleChatLock(chat.id, currentUser.uid);
    setIsLocked(!isLocked);
  };

  return (
    <div className="flex-1 flex flex-col h-full bg-slate-50 dark:bg-slate-900/40 animate-in fade-in duration-300">
      {/* Header */}
      <div className="p-3 md:p-4 flex items-center justify-between glass z-10 border-b border-slate-200 dark:border-slate-800">
        <div className="flex items-center gap-3">
          <button onClick={onClose} className="lg:hidden p-2 rounded-full hover:bg-slate-200 dark:hover:bg-slate-800 transition-colors">
            <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M15 19l-7-7 7-7" />
            </svg>
          </button>

          <div className="relative cursor-pointer" onClick={() => !isGroup && otherUser && onUserClick(otherUser)}>
            <img 
              src={isGroup ? (chat.groupIcon || `https://picsum.photos/seed/${chat.id}/200`) : otherUser?.photoURL} 
              className="w-10 h-10 rounded-full object-cover border border-slate-200 dark:border-slate-700" 
              alt="Profile" 
            />
            {!isGroup && otherUser?.status === 'online' && (
              <div className="absolute bottom-0 right-0 w-3 h-3 bg-green-500 rounded-full border-2 border-white dark:border-slate-900"></div>
            )}
          </div>

          <div className="min-w-0">
            <h3 className="font-bold text-sm leading-none flex items-center gap-2 truncate">
              {isGroup ? chat.name : otherUser?.name}
              {isLocked && (
                <svg className="w-3.5 h-3.5 text-indigo-500 shrink-0" fill="currentColor" viewBox="0 0 24 24">
                  <path d="M12 17c1.1 0 2-.9 2-2s-.9-2-2-2-2 .9-2 2 .9 2 2 2zm6-9h-1V6c0-2.76-2.24-5-5-5S7 3.24 7 6v2H6c-1.1 0-2 .9-2 2v10c0 1.1.9 2 2 2h12c1.1 0 2-.9 2-2V10c0-1.1-.9-2-2-2zm-6-5c1.66 0 3 1.34 3 3v2H9V6c0-1.66 1.34-3 3-3z"/>
                </svg>
              )}
            </h3>
            <span className="text-[10px] text-slate-500 font-medium">
              {isGroup ? `${chat.participants.length} members` : (otherUser?.status === 'online' ? 'Online' : 'Offline')}
            </span>
          </div>
        </div>

        <button 
          onClick={handleToggleLock}
          className={`p-2 rounded-xl transition-all ${isLocked ? 'bg-indigo-500 text-white shadow-lg shadow-indigo-500/20' : 'hover:bg-slate-200 dark:hover:bg-slate-800 text-slate-400'}`}
          title={isLocked ? "Unlock Chat" : "Lock Chat"}
        >
          <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 15v2m-6 4h12a2 2 0 002-2v-6a2 2 0 00-2-2H6a2 2 0 00-2 2v6a2 2 0 002 2zm10-10V7a4 4 0 00-8 0v4h8z" />
          </svg>
        </button>
      </div>

      {/* Messages List */}
      <div ref={scrollRef} className="flex-1 overflow-y-auto p-4 space-y-3 scroll-smooth">
        {messages.length === 0 && !isTyping && (
          <div className="h-full flex flex-col items-center justify-center opacity-40 text-center p-8">
            <div className="w-16 h-16 bg-slate-200 dark:bg-slate-800 rounded-full flex items-center justify-center mb-4">
              <svg className="w-8 h-8" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M8 12h.01M12 12h.01M16 12h.01M21 12c0 4.418-4.03 8-9 8a9.863 9.863 0 01-4.255-.949L3 20l1.395-3.72C3.512 15.042 3 13.574 3 12c0-4.418 4.03-8 9-8s9 3.582 9 8z" /></svg>
            </div>
            <p className="text-sm font-medium">No messages yet. Say hi!</p>
            <p className="text-[10px] mt-1 italic">Type /ai followed by a question to talk to Gemini.</p>
          </div>
        )}

        {messages.map((msg, index) => (
          <MessageBubble 
            key={msg.id || index} 
            message={msg} 
            isOwn={msg.senderId === currentUser.uid} 
            isAI={msg.senderId === 'gemini_ai'} 
            onReply={() => {}} 
            onForward={() => {}} 
          />
        ))}

        {isTyping && (
          <div className="flex items-center gap-2 ml-2 animate-in fade-in slide-in-from-left-2">
            <div className="flex gap-1">
              <div className="w-1.5 h-1.5 bg-indigo-400 rounded-full animate-bounce [animation-delay:-0.3s]"></div>
              <div className="w-1.5 h-1.5 bg-indigo-500 rounded-full animate-bounce [animation-delay:-0.15s]"></div>
              <div className="w-1.5 h-1.5 bg-indigo-600 rounded-full animate-bounce"></div>
            </div>
            <span className="text-[10px] font-bold text-indigo-500 uppercase tracking-widest">Gemini is thinking</span>
          </div>
        )}
      </div>

      {/* Input Area */}
      <form onSubmit={handleSend} className="p-3 md:p-4 glass border-t border-slate-200 dark:border-slate-800 flex gap-2 md:gap-3">
        <input 
          type="text" 
          value={inputText} 
          onChange={e => setInputText(e.target.value)}
          placeholder="Type a message..." 
          className="flex-1 bg-slate-100 dark:bg-slate-800/50 rounded-2xl px-5 py-3 text-sm outline-none focus:ring-2 focus:ring-indigo-500/50 transition-all border border-transparent focus:bg-white dark:focus:bg-slate-800"
        />
        <button 
          type="submit" 
          disabled={!inputText.trim()}
          className="p-3 bg-indigo-500 text-white rounded-2xl hover:bg-indigo-600 disabled:opacity-40 disabled:hover:bg-indigo-500 active:scale-90 transition-all shadow-lg shadow-indigo-500/20 shrink-0"
        >
          <svg className="w-5 h-5 rotate-90" fill="none" stroke="currentColor" viewBox="0 0 24 24">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M12 19l9 2-9-18-9 18 9-2zm0 0v-8" />
          </svg>
        </button>
      </form>
    </div>
  );
};
